{"command": "cd /workspace; cat > /tmp/flip.py <<'EOF'
import os, pty, sys, select, fcntl, termios, struct
def run(argv, cwd=None, cols=80, rows=24):
    pid, fd = pty.fork()
    if pid == 0:
        if cwd: os.chdir(cwd)
        os.execv(argv[0], argv)
    fcntl.ioctl(fd, termios.TIOCSWINSZ, struct.pack('HHHH', rows, cols, 0, 0))
    out=b''
    while True:
        try:
            r,_,_ = select.select([fd],[],[],2)
            if not r: break
            d = os.read(fd, 65536)
            if not d: break
            out += d
        except OSError: break
    os.waitpid(pid,0)
    return out.decode(errors='replace')
def nextline(argv, cols):
    o = run(argv, cols=cols)
    lines = o.rstrip("\r\n").split("\r\n")
    return lines[-1]
def isnl(argv, cols):
    return nextline(argv, cols).startswith("          ")
def flip(argv, lo=5, hi=250):
    if isnl(argv, hi): return None
    if not isnl(argv, lo): return lo
    while hi-lo > 1:
        mid = (hi+lo)//2
        if isnl(argv, mid): lo = mid
        else: hi = mid
    return hi
for cmd in sys.argv[1:]:
    print(cmd, flip([ "./executable", cmd, "-h"]))
EOF
python3 /tmp/flip.py root add restart wait pause status log clean group reset follow completions env remove send switch edit stash enqueue start shutdown kill parallel 2>&1"}

