{"command": "cd /workspace; cat > src/model.rs <<'RSEOF'
//! Data model for the command line interface definition.
//!
//! The structures mirror the metadata that `clap` derives from the derive
//! macros: every command knows its about/long-about texts, its options, its
//! positional arguments and its subcommands.

#[derive(Clone, Copy, PartialEq)]
pub enum Kind {
    /// A boolean flag, may be repeated (`-v`, `-vv`).
    Flag,
    /// Takes exactly one value.
    Value,
    /// Takes one or more values.
    MultiValue,
}

#[derive(Clone, Copy)]
pub struct Arg {
    pub id: &'static str,
    pub short: Option<char>,
    pub long: &'static str,
    pub value_name: Option<&'static str>,
    pub help: &'static str,
    pub long_help: &'static str,
    pub multi: bool,
    pub required: bool,
    pub possible: &'static [&'static str],
    pub default: Option<&'static str>,
    pub kind: Kind,
}

impl Arg {
    /// The text that is rendered in the "Options:" section.
    pub fn spec(&self) -> String {
        let mut out = String::new();
        match self.short {
            Some(s) => {
                out.push('-');
                out.push(s);
                out.push_str(", ");
            }
            None => out.push_str("    "),
        }
        out.push_str("--");
        out.push_str(self.long);
        if let Some(v) = self.value_name {
            out.push_str(" <");
            out.push_str(v);
            out.push('>');
        }
        if self.multi {
            out.push_str("...");
        }
        out
    }

    /// The string that is shown in error messages / usage lines.
    pub fn usage(&self) -> String {
        let mut out = String::new();
        out.push_str("--");
        out.push_str(self.long);
        if let Some(v) = self.value_name {
            out.push_str(" <");
            out.push_str(v);
            out.push('>');
        }
        if self.multi {
            out.push_str("...");
        }
        out
    }

    pub fn takes_value(&self) -> bool {
        !matches!(self.kind, Kind::Flag)
    }
}

#[derive(Clone, Copy)]
pub struct Positional {
    pub id: &'static str,
    pub name: &'static str,
    pub help: &'static str,
    pub long_help: &'static str,
    pub required: bool,
    pub multi: bool,
}

impl Positional {
    pub fn spec(&self) -> String {
        let mut out = String::new();
        if self.required {
            out.push('<');
            out.push_str(self.name);
            out.push('>');
        } else {
            out.push('[');
            out.push_str(self.name);
            out.push(']');
        }
        if self.multi {
            out.push_str("...");
        }
        out
    }

    /// Rendering inside a usage line.
    pub fn usage(&self) -> String {
        self.spec()
    }
}

#[derive(Clone, Copy)]
pub struct Cmd {
    pub name: &'static str,
    pub about: &'static str,
    pub long_about: &'static str,
    pub args: &'static [Arg],
    pub positionals: &'static [Positional],
    pub subcommands: &'static [Cmd],
    /// `true` when a subcommand has to be supplied (`env`, `env set`, ...).
    pub sub_required: bool,
    /// Text printed after the argument sections (`DELAY FORMAT`).
    pub after_help: &'static str,
    /// Whether the command knows a long about/long help text.  This decides
    /// whether `-h` advertises `--help`.
    pub has_long: bool,
}

impl Cmd {
    pub fn find_sub(&self, name: &str) -> Option<&'static Cmd> {
        self.subcommands.iter().find(|c| c.name == name)
    }
    pub fn find_long(&self, name: &str) -> Option<&Arg> {
        self.args.iter().find(|a| a.long == name)
    }
    pub fn find_short(&self, c: char) -> Option<&Arg> {
        self.args.iter().find(|a| a.short == Some(c))
    }
    pub fn positionals_with_help(&self, long: bool) -> Vec<&Positional> {
        self.positionals
            .iter()
            .filter(|p| !p.help.is_empty() || long)
            .collect()
    }
}

/// Locate a command by walking a chain of subcommand names.
pub fn lookup(mut cmd: &'static Cmd, path: &[String]) -> Option<&'static Cmd> {
    for part in path {
        match cmd.find_sub(part) {
            Some(c) => cmd = c,
            None => return None,
        }
    }
    Some(cmd)
}
RSEOF
