{"command": "cd /workspace; cat > src/help.rs <<'RSEOF'
//! Rendering of `--help` output, usage lines and text wrapping.
//!
//! The layout is a reimplementation of the layout algorithm used by the
//! argument parser of the original binary.

use crate::model::{Arg, Cmd, Positional};

/// Terminal width that is used when the real width cannot be determined.
pub const DEFAULT_TERM_WIDTH: usize = 100;

/// Wrap a single logical line to `limit` visible columns.
///
/// Words are separated by whitespace, the whitespace itself is kept so that
/// column aligned output (for instance the examples in the `DELAY FORMAT`
/// block) is preserved.  A word that does not fit is emitted on its own line.
fn wrap_tokens(content: &str, limit: usize) -> Vec<String> {
    let mut tokens: Vec<&str> = Vec::new();
    let bytes = content.as_bytes();
    let mut start = 0;
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b' ' {
            i += 1;
            tokens.push(&content[start..i]);
            start = i;
        } else {
            i += 1;
        }
    }
    if start < content.len() {
        tokens.push(&content[start..]);
    }

    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut cur_w = 0usize;
    for tok in tokens {
        let w = tok.chars().count();
        if !cur.is_empty() && cur_w + w > limit {
            // strip the trailing separator of the previous token
            let trimmed = cur.trim_end_matches(' ').to_string();
            out.push(trimmed);
            cur.clear();
            cur_w = 0;
        }
        cur.push_str(tok);
        cur_w += w;
    }
    if !cur.is_empty() {
        out.push(cur.trim_end_matches(' ').to_string());
    }
    if out.is_empty() {
        out.push(String::new());
    }
    out
}

/// Wrap a multi line text block.
///
/// `block_indent` is the indentation that is added in front of every line,
/// the hanging indent of a paragraph is the leading whitespace of the source
/// line itself.
pub fn wrap_block(text: &str, term_w: usize, block_indent: usize) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for line in text.split('\n') {
        let lead = line.len() - line.trim_start_matches(' ').len();
        let content = &line[lead..];
        let limit = term_w.saturating_sub(block_indent).saturating_sub(lead);
        let hang = block_indent + lead;
        for piece in wrap_tokens(content, limit) {
            let mut s = String::new();
            for _ in 0..hang {
                s.push(' ');
            }
            s.push_str(&piece);
            out.push(s);
        }
    }
    out
}

/// Number of display columns of a string.
pub fn width(s: &str) -> usize {
    s.chars().count()
}

/// The help text that is displayed for an argument in the given mode.
pub fn arg_help(arg: &Arg, long: bool) -> &'static str {
    if long && !arg.long_help.is_empty() {
        arg.long_help
    } else {
        arg.help
    }
}

pub fn positional_help(p: &Positional, long: bool) -> &'static str {
    if long && !p.long_help.is_empty() {
        p.long_help
    } else {
        p.help
    }
}

/// The `[default: ..] [possible values: ..]` annotations of an argument.
pub fn spec_vals(arg: &Arg) -> Vec<String> {
    let mut out = Vec::new();
    if let Some(d) = arg.default {
        out.push(format!("[default: {}]", d));
    }
    if !arg.possible.is_empty() {
        out.push(format!("[possible values: {}]", arg.possible.join(", ")));
    }
    out
}

struct SectionArg {
    spec: String,
    help: &'static str,
    vals: Vec<String>,
}

/// Render one section (Arguments / Commands / Options) of the help output.
fn render_section(entries: &[SectionArg], term_w: usize, long: bool, blank_between: bool) -> String {
    let longest = entries
        .iter()
        .map(|e| width(&e.spec))
        .max()
        .unwrap_or(2)
        .max(2);
    let taken = 2 + longest + 2;

    // Decide whether every help text is put on the line following the spec.
    let next_line_help = {
        let mut any = false;
        for e in entries {
            let mut full = e.help.to_string();
            for v in &e.vals {
                full.push(' ');
                full.push_str(v);
            }
            let w = width(&full);
            if term_w < 5 * taken / 2 + (5 * taken % 2 != 0) as usize
                || term_w < taken + w
            {
                any = true;
            }
        }
        any
    };

    let mut out = String::new();
    let indent = if next_line_help { 10 } else { taken };
    let mut first = true;
    for e in entries {
        if !first {
            if next_line_help && blank_between {
                out.push('\n');
            }
            out.push('\n');
        }
        first = false;
        if next_line_help {
            out.push_str("  ");
            out.push_str(&e.spec);
            out.push('\n');
            let block = if e.vals.is_empty() {
                e.help.to_string()
            } else {
                let mut s = e.help.to_string();
                s.push('\n');
                s.push('\n');
                s.push_str(&e.vals.join("\n"));
                s
            };
            for l in wrap_block(&block, term_w, indent) {
                out.push_str(&l);
                out.push('\n');
            }
        } else {
            out.push_str("  ");
            out.push_str(&e.spec);
            let pad = longest - width(&e.spec) + 2;
            for _ in 0..pad {
                out.push(' ');
            }
            let mut full = e.help.to_string();
            for v in &e.vals {
                full.push(' ');
                full.push_str(v);
            }
            for (i, l) in wrap_block(&full, term_w, indent).into_iter().enumerate() {
                if i > 0 {
                    for _ in 0..indent {
                        out.push(' ');
                    }
                }
                out.push_str(&l);
                out.push('\n');
            }
        }
    }
    out
}

fn option_entries(cmd: &Cmd, long: bool) -> Vec<SectionArg> {
    cmd.args
        .iter()
        .map(|a| SectionArg {
            spec: a.spec(),
            help: arg_help(a, long),
            vals: spec_vals(a),
        })
        .collect()
}

fn positional_entries(cmd: &Cmd, long: bool) -> Vec<SectionArg> {
    cmd.positionals
        .iter()
        .filter(|p| long || !p.help.is_empty())
        .map(|p| SectionArg {
            spec: p.spec(),
            help: positional_help(p, long),
            vals: Vec::new(),
        })
        .collect()
}

fn subcommand_entries(cmd: &Cmd) -> Vec<SectionArg> {
    cmd.subcommands
        .iter()
        .map(|c| SectionArg {
            spec: c.name.to_string(),
            help: c.about,
            vals: Vec::new(),
        })
        .collect()
}

/// The complete `--help`/`-h` output for a command.
pub fn render_help(
    cmd: &Cmd,
    bin_name: &str,
    path: &[&str],
    term_w: usize,
    long: bool,
) -> String {
    let mut out = String::new();
    let about = if long && !cmd.long_about.is_empty() {
        cmd.long_about
    } else {
        cmd.about
    };
    for l in wrap_block(about, term_w, 0) {
        out.push_str(&l);
        out.push('\n');
    }
    out.push('\n');
    out.push_str("Usage: ");
    out.push_str(&full_usage(cmd, bin_name, path));
    out.push('\n');

    let pos = positional_entries(cmd, long);
    let subs = subcommand_entries(cmd);
    let opts = option_entries(cmd, long);
    let blank_between = long;

    if !pos.is_empty() {
        out.push('\n');
        out.push_str("Arguments:\n");
        out.push_str(&render_section(&pos, term_w, long, blank_between));
    }
    if !subs.is_empty() {
        out.push('\n');
        out.push_str("Commands:\n");
        out.push_str(&render_section(&subs, term_w, long, blank_between));
    }
    if !opts.is_empty() {
        out.push('\n');
        out.push_str("Options:\n");
        out.push_str(&render_section(&opts, term_w, long, blank_between));
    }
    if !cmd.after_help.is_empty() {
        out.push('\n');
        out.push('\n');
        out.push_str(&wrap_block(cmd.after_help, term_w, 0).join("\n"));
        out.push('\n');
    }
    out
}

/// The complete usage line of a command.
pub fn full_usage(cmd: &Cmd, bin_name: &str, path: &[&str]) -> String {
    let mut out = String::new();
    out.push_str(bin_name);
    for p in path {
        out.push(' ');
        out.push_str(p);
    }
    let has_options = cmd.args.iter().any(|a| !matches!(a.id, "help" | "version"));
    if has_options {
        out.push_str(" [OPTIONS]");
    }
    for p in cmd.positionals {
        out.push(' ');
        out.push_str(&p.usage());
    }
    if !cmd.subcommands.is_empty() {
        if cmd.sub_required {
            out.push_str(" <COMMAND>");
        } else {
            out.push_str(" [COMMAND]");
        }
    }
    out
}

/// Usage line used inside error messages when some arguments were consumed.
pub fn smart_usage(
    cmd: &Cmd,
    bin_name: &str,
    path: &[&str],
    used: &[String],
) -> String {
    let mut out = String::new();
    out.push_str(bin_name);
    for p in path {
        out.push(' ');
        out.push_str(p);
    }
    for id in used {
        out.push(' ');
        out.push_str(id);
    }
    for p in cmd.positionals {
        out.push(' ');
        out.push_str(&p.usage());
    }
    out
}
