fn spaces(n: usize) -> String {
    " ".repeat(n)
}

/// Display width of a string.
pub fn width(s: &str) -> usize {
    s.chars().count()
}

/// Wrap one logical line to `limit` columns.  Whitespace is preserved so that
/// aligned text (see the `DELAY FORMAT` block) stays aligned; a word that does
/// not fit is emitted on a line of its own.
fn wrap_tokens(content: &str, limit: usize) -> Vec<String> {
    let mut tokens: Vec<&str> = Vec::new();
    let bytes = content.as_bytes();
    let mut start = 0usize;
    let mut i = 0usize;
    while i < bytes.len() {
        if bytes[i] == b' ' {
            i += 1;
            tokens.push(&content[start..i]);
            start = i;
        } else {
            i += 1;
        }
    }
    if start < content.len() {
        tokens.push(&content[start..]);
    }

    let mut out: Vec<String> = Vec::new();
    let mut cur = String::new();
    let mut cur_w = 0usize;
    for tok in tokens {
        let w = width(tok);
        if !cur.is_empty() && cur_w + w > limit {
            out.push(cur.trim_end_matches(' ').to_string());
            cur.clear();
            cur_w = 0;
        }
        cur.push_str(tok);
        cur_w += w;
    }
    if !cur.is_empty() {
        out.push(cur.trim_end_matches(' ').to_string());
    }
    if out.is_empty() {
        out.push(String::new());
    }
    out
}

/// Wrap a text block.  Every source line is wrapped separately; the hanging
/// indent is the leading whitespace of the source line.
pub fn wrap_block(text: &str, term_w: usize, block_indent: usize) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();
    for line in text.split('\n') {
        let lead = line.len() - line.trim_start_matches(' ').len();
        let content = &line[lead..];
        let limit = term_w.saturating_sub(block_indent).saturating_sub(lead);
        let hang = block_indent + lead;
        for piece in wrap_tokens(content, limit) {
            out.push(format!("{}{}", spaces(hang), piece));
        }
    }
    out
}

/// The help text of an argument in the given mode.
pub fn arg_help(arg: &Arg, long: bool) -> &'static str {
    if long && !arg.long_help.is_empty() {
        arg.long_help
    } else {
        arg.help
    }
}

pub fn positional_help(p: &Positional, long: bool) -> &'static str {
    if long && !p.long_help.is_empty() {
        p.long_help
    } else {
        p.help
    }
}

/// `[default: ..]` / `[possible values: ..]` annotations.
pub fn spec_vals(arg: &Arg) -> Vec<String> {
    let mut out = Vec::new();
    if let Some(d) = arg.default {
        out.push(format!("[default: {}]", d));
    }
    if !arg.possible.is_empty() {
        out.push(format!("[possible values: {}]", arg.possible.join(", ")));
    }
    out
}

struct Entry {
    spec: String,
    help: &'static str,
    vals: Vec<String>,
}

fn render_section(entries: &[Entry], term_w: usize, long: bool) -> String {
    let longest = entries
        .iter()
        .map(|e| width(&e.spec))
        .max()
        .unwrap_or(2)
        .max(2);
    let taken = 2 + longest + 2;
    let wrapped_limit = (5 * taken + 1) / 2;

    let mut next_line_help = false;
    for e in entries {
        let w = width(e.help) + e.vals.iter().map(|v| width(v) + 1).sum::<usize>();
        if term_w < wrapped_limit.min(taken + w) {
            next_line_help = true;
        }
    }

    let mut out = String::new();
    let mut first = true;
    for e in entries {
        if !first {
            if long && next_line_help {
                out.push('\n');
            }
            out.push('\n');
        }
        first = false;
        if next_line_help {
            out.push_str("  ");
            out.push_str(&e.spec);
            out.push('\n');
            let block = if long && !e.vals.is_empty() {
                let mut s = e.help.to_string();
                s.push_str("\n\n");
                s.push_str(&e.vals.join("\n"));
                s
            } else if !e.vals.is_empty() {
                let mut s = e.help.to_string();
                for v in &e.vals {
                    s.push(' ');
                    s.push_str(v);
                }
                s
            } else {
                e.help.to_string()
            };
            for l in wrap_block(&block, term_w, 10) {
                out.push_str(&l);
                out.push('\n');
            }
        } else {
            out.push_str("  ");
            out.push_str(&e.spec);
            out.push_str(&spaces(longest - width(&e.spec) + 2));
            let mut full = e.help.to_string();
            for v in &e.vals {
                full.push(' ');
                full.push_str(v);
            }
            let indent = taken;
            for (i, l) in wrap_block(&full, term_w, indent).into_iter().enumerate() {
                if i > 0 {
                    out.push_str(&spaces(indent));
                }
                out.push_str(&l);
                out.push('\n');
            }
        }
    }
    out
