/// Does the command know a long help text that differs from the short one?
pub fn has_long_variant(cmd: &Cmd) -> bool {
    cmd.has_long
}

fn option_entries(cmd: &Cmd, long: bool) -> Vec<Entry> {
    cmd.args
        .iter()
        .map(|a| Entry {
            spec: a.spec(),
            help: arg_help(a, long),
            vals: spec_vals(a),
        })
        .collect()
}

fn positional_entries(cmd: &Cmd, long: bool) -> Vec<Entry> {
    cmd.positionals
        .iter()
        .filter(|p| long || !p.help.is_empty())
        .map(|p| Entry {
            spec: p.spec(),
            help: positional_help(p, long),
            vals: Vec::new(),
        })
        .collect()
}

fn subcommand_entries(cmd: &Cmd) -> Vec<Entry> {
    cmd.subcommands
        .iter()
        .map(|c| Entry {
            spec: c.name.to_string(),
            help: c.about,
            vals: Vec::new(),
        })
        .collect()
}

/// Complete `--help` / `-h` output of a command.
pub fn render_help(cmd: &Cmd, bin_name: &str, path: &[&str], term_w: usize, long: bool) -> String {
    let mut out = String::new();
    let about = if long && !cmd.long_about.is_empty() {
        cmd.long_about
    } else {
        cmd.about
    };
    for l in wrap_block(about, term_w, 0) {
        out.push_str(&l);
        out.push('\n');
    }
    out.push('\n');
    out.push_str("Usage: ");
    out.push_str(&full_usage(cmd, bin_name, path));
    out.push('\n');

    let long_args = long && has_long_variant(cmd);

    let pos = positional_entries(cmd, long);
    let subs = subcommand_entries(cmd);
    let opts = option_entries(cmd, long);

    if !pos.is_empty() {
        out.push('\n');
        out.push_str("Arguments:\n");
        if long_args {
            out.push_str(&render_next(&pos, term_w, long));
        } else {
            out.push_str(&render_section(&pos, term_w, long));
        }
    }
    if !subs.is_empty() {
        out.push('\n');
        out.push_str("Commands:\n");
        out.push_str(&render_section(&subs, term_w, long));
    }
    if !opts.is_empty() {
        out.push('\n');
        out.push_str("Options:\n");
        if long_args {
            out.push_str(&render_next(&opts, term_w, long));
        } else {
            out.push_str(&render_section(&opts, term_w, long));
        }
    }
    if !cmd.after_help.is_empty() {
        out.push_str("\n\n");
        out.push_str(&wrap_block(cmd.after_help, term_w, 0).join("\n"));
        out.push('\n');
    }
    out
}

/// Render a section with the help text always below the specification.
fn render_next(entries: &[Entry], term_w: usize, long: bool) -> String {
    let mut out = String::new();
    let mut first = true;
    for e in entries {
        if !first {
            if long {
                out.push('\n');
            }
            out.push('\n');
        }
        first = false;
        out.push_str("  ");
        out.push_str(&e.spec);
        out.push('\n');
        let block = if long && !e.vals.is_empty() {
            let mut s = e.help.to_string();
            s.push_str("\n\n");
            s.push_str(&e.vals.join("\n"));
            s
        } else if !e.vals.is_empty() {
            let mut s = e.help.to_string();
            for v in &e.vals {
                s.push(' ');
                s.push_str(v);
            }
            s
        } else {
            e.help.to_string()
        };
        for l in wrap_block(&block, term_w, 10) {
            out.push_str(&l);
            out.push('\n');
        }
    }
    out
}

/// The full usage line of a command.
pub fn full_usage(cmd: &Cmd, bin_name: &str, path: &[&str]) -> String {
    let mut out = String::new();
    out.push_str(bin_name);
    for p in path {
        out.push(' ');
        out.push_str(p);
    }
    let has_options = cmd
        .args
        .iter()
        .any(|a| a.id != "help" && a.id != "version");
    if has_options {
        out.push_str(" [OPTIONS]");
    }
    for p in cmd.positionals {
        out.push(' ');
        out.push_str(&p.usage());
    }
    if !cmd.subcommands.is_empty() {
        out.push(' ');
        out.push_str(if cmd.sub_required { "<COMMAND>" } else { "[COMMAND]" });
    }
    out
}

/// Usage line of an error message listing the arguments that were used.
pub fn smart_usage(cmd: &Cmd, bin_name: &str, path: &[&str], used: &[String]) -> String {
    let mut out = String::new();
    out.push_str(bin_name);
    for p in path {
        out.push(' ');
        out.push_str(p);
    }
    for id in used {
        out.push(' ');
        out.push_str(id);
    }
    for p in cmd.positionals {
        out.push(' ');
        out.push_str(&p.usage());
    }
    out
}
