{"command": "cd /workspace; cat > src/parser.rs <<'RSEOF'
//! Command line parsing.
//!
//! The behaviour (including the wording of every error message) follows the
//! argument parser of the original binary.

use crate::cli::{ROOT, SUBCOMMANDS};
use crate::help::{full_usage, smart_usage, spec_vals, width};
use crate::model::{Arg, Cmd, Kind};
use crate::subcmd_alias;

/// Everything that was successfully parsed.
pub struct Matches {
    pub path: Vec<&'static Cmd>,
    pub values: Vec<(&'static Arg, Vec<String>)>,
    pub positionals: Vec<String>,
}

impl Matches {
    pub fn cmd(&self) -> &'static Cmd {
        self.path.last().copied().unwrap_or(&ROOT)
    }
    pub fn get(&self, id: &str) -> Option<&Vec<String>> {
        self.values
            .iter()
            .find(|(a, _)| a.id == id)
            .map(|(_, v)| v)
    }
    pub fn flag(&self, id: &str) -> bool {
        self.get(id).is_some()
    }
    pub fn value(&self, id: &str) -> Option<&String> {
        self.get(id).and_then(|v| v.first())
    }
    /// The amount of occurrences of a counting flag.
    pub fn count(&self, id: &str) -> usize {
        self.get(id).map(|v| v.len()).unwrap_or(0)
    }
    /// The amount of values of a multi value option.
    pub fn multi_len(&self, id: &str) -> usize {
        self.get(id).map(|v| v.len()).unwrap_or(0)
    }
}

/// An error that is rendered exactly like the original program does.
pub struct ClapError {
    pub message: String,
    /// Additional line rendered below the message.
    pub detail: Option<String>,
    /// `tip:` block.
    pub tip: Option<String>,
    pub usage: Option<String>,
}

impl ClapError {
    pub fn render(&self) -> String {
        let mut out = format!("error: {}\n", self.message);
        if let Some(d) = &self.detail {
            out.push_str(d);
            out.push('\n');
        }
        if let Some(t) = &self.tip {
            out.push('\n');
            out.push_str("  tip: ");
            out.push_str(t);
            out.push('\n');
        }
        if let Some(u) = &self.usage {
            out.push('\n');
            out.push_str("Usage: ");
            out.push_str(u);
            out.push('\n');
        }
        out.push('\n');
        out.push_str("For more information, try '--help'.\n");
        out
    }
}

fn invalid_subcommand(name: &str, candidates: &[&str], usage: String) -> ClapError {
    let tips = did_you_mean(name, candidates);
    let tip = match tips.len() {
        0 => None,
        1 => Some(format!("a similar subcommand exists: '{}'", tips[0])),
        _ => Some(format!(
            "some similar subcommands exist: {}",
            tips.iter()
                .map(|t| format!("'{}'", t))
                .collect::<Vec<_>>()
                .join(", ")
        )),
    };
    ClapError {
        message: format!("unrecognized subcommand '{}'", name),
        detail: None,
        tip,
        usage: Some(usage),
    }
}

fn invalid_value(
    value: &str,
    arg: &Arg,
    message: &str,
    usage: Option<String>,
) -> ClapError {
    let possible = spec_vals(arg);
    let mut detail = None;
    if let Some(p) = possible.first() {
        detail = Some(p.clone());
    }
    let tip = if !arg.possible.is_empty() {
        let tips = did_you_mean(value, arg.possible);
        match tips.len() {
            0 => None,
            1 => Some(format!("a similar value exists: '{}'", tips[0])),
            _ => Some(format!(
                "some similar values exist: {}",
                tips.iter().map(|t| format!("'{}'", t)).collect::<Vec<_>>().join(", ")
            )),
        }
    } else {
        None
    };
    let message = if detail.is_some() {
        format!("invalid value '{}' for '{}'", value, arg.usage())
    } else {
        format!(
            "invalid value '{}' for '{}': {}",
            value,
            arg.usage(),
            message
        )
    };
    ClapError {
        message,
        detail,
        tip,
        usage: None,
    }
}

/// Jaro similarity, matching the implementation of the original binary.
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (al, bl) = (a.len(), b.len());
    if al == 0 && bl == 0 {
        return 1.0;
    }
    if al == 0 || bl == 0 {
        return 0.0;
    }
    if al == 1 && bl == 1 {
        return if a[0] == b[0] { 1.0 } else { 0.0 };
    }
    let search_range = (al.max(bl) / 2) - 1;
    let mut consumed = vec![false; bl];
    let mut matches = 0.0f64;
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for (i, a_elem) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = (bl - 1).min(i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for (j, b_elem) in b.iter().enumerate() {
            if min_bound <= j && j <= max_bound && a_elem == b_elem && !consumed[j] {
                consumed[j] = true;
                matches += 1.0;
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    if matches == 0.0 {
        0.0
    } else {
        (1.0 / 3.0)
            * ((matches / al as f64)
                + (matches / bl as f64)
                + ((matches - transpositions) / matches))
    }
}

fn did_you_mean(input: &str, possible: &[&str]) -> Vec<String> {
    let mut candidates: Vec<(f64, String)> = possible
        .iter()
        .map(|p| (jaro(input, p), (*p).to_string()))
        .filter(|(c, _)| *c >= 0.7)
        .collect();
    candidates.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    candidates.into_iter().map(|(_, p)| p).collect()
}

/// All names (and hidden aliases) of the subcommands of `cmd`.
fn subcommand_names(cmd: &Cmd) -> Vec<&'static str> {
    let mut out = Vec::new();
    for sc in cmd.subcommands {
        out.push(sc.name);
        for alias in subcmd_alias::aliases_of(sc.name) {
            out.push(alias);
        }
    }
    out
}

pub enum Outcome {
    Help { long: bool, cmd: &'static Cmd, path: Vec<&'static Cmd> },
    Version,
    Matches(Box<Matches>),
}

/// Print the help of a subcommand chain (used by the `help` subcommand).
pub struct HelpRequest {
    pub cmd: &'static Cmd,
    pub path: Vec<&'static Cmd>,
}

pub fn parse(argv: &[String], bin_name: &str) -> Result<Outcome, ClapError> {
    let mut cmd: &'static Cmd = &ROOT;
    let mut path: Vec<&'static Cmd> = Vec::new();
    let mut values: Vec<(&'static Arg, Vec<String>)> = Vec::new();
    let mut positionals: Vec<String> = Vec::new();
    let mut used: Vec<String> = Vec::new();
    let mut positional_idx = 0usize;
    let mut only_positional = false;
    let mut idx = 0usize;

    while idx < argv.len() {
        let token = &argv[idx];
        idx += 1;
        if only_positional {
            push_positional(cmd, &mut positionals, &mut positional_idx, token)?;
            continue;
        }
        if token == "--" {
            only_positional = true;
            continue;
        }
        if token.starts_with("--") && token.len() > 2 {
            let body = &token[2..];
            let (name, inline) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            if name == "help" && cmd.find_long("help").is_some() {
                return Ok(Outcome::Help {
                    long: true,
                    cmd,
                    path: path.clone(),
                });
            }
            if name == "version" && cmd.find_long("version").is_some() {
                return Ok(Outcome::Version);
            }
            match cmd.find_long(name) {
                Some(arg) => {
                    if arg.takes_value() {
                        let value = match inline {
                            Some(v) => v,
                            None => {
                                if idx < argv.len() {
                                    let v = argv[idx].clone();
                                    idx += 1;
                                    v
                                } else {
                                    return Err(value_required(arg));
                                }
                            }
                        };
                        validate_value(arg, &value)?;
                        store(&mut values, arg, value, &mut used);
                        if arg.kind == Kind::Value {
                            // a single value option only accepts one value
                        }
                    } else if inline.is_some() {
                        return Err(ClapError {
                            message: format!(
                                "unexpected value '{}' for '--{}' found; no more were expected",
                                inline.unwrap(),
                                name
                            ),
                            detail: None,
                            tip: None,
                            usage: Some(full_usage(cmd, bin_name, &path_names(&path))),
                        });
                    } else {
                        store(&mut values, arg, String::new(), &mut used);
                    }
                }
                None => {
                    return Err(unexpected_argument(
                        cmd,
                        &format!("--{}", name),
                        bin_name,
                        &path,
                        !cmd.positionals.is_empty(),
                    ))
                }
            }
            continue;
        }
        if token.starts_with('-') && token.len() > 1 {
            let chars: Vec<char> = token[1..].chars().collect();
            let mut ci = 0usize;
            while ci < chars.len() {
                let c = chars[ci];
                ci += 1;
                if c == 'h' && cmd.find_short('h').is_some() {
                    return Ok(Outcome::Help {
                        long: false,
                        cmd,
                        path: path.clone(),
                    });
                }
                if c == 'V' && cmd.find_short('V').is_some() {
                    return Ok(Outcome::Version);
                }
                match cmd.find_short(c) {
                    Some(arg) => {
                        if arg.takes_value() {
                            let rest: String = chars[ci..].iter().collect();
                            let value = if !rest.is_empty() {
                                ci = chars.len();
                                rest.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest)
                            } else if idx < argv.len() {
                                let v = argv[idx].clone();
                                idx += 1;
                                v
                            } else {
                                return Err(value_required(arg));
                            };
                            validate_value(arg, &value)?;
                            store(&mut values, arg, value, &mut used);
                        } else {
                            store(&mut values, arg, String::new(), &mut used);
                        }
                    }
                    None => {
                        return Err(unexpected_argument(
                            cmd,
                            &format!("-{}", c),
                            bin_name,
                            &path,
                            !cmd.positionals.is_empty(),
                        ))
                    }
                }
            }
            continue;
        }
        // Positional or subcommand
        if !cmd.subcommands.is_empty() {
            let aliases = subcommand_names(cmd);
            if let Some(sub) = cmd.find_sub(token) {
                cmd = sub;
                path.push(sub);
                used.clear();
                positionals.clear();
                positional_idx = 0;
                continue;
            }
            if aliases.iter().any(|a| *a == token.as_str()) {
                // alias of a subcommand
                let target = cmd
                    .subcommands
                    .iter()
                    .find(|sc| subcmd_alias::aliases_of(sc.name).contains(&token.as_str()))
                    .unwrap();
                cmd = target;
                path.push(target);
                used.clear();
                positionals.clear();
                positional_idx = 0;
                continue;
            }
            // The `help` subcommand is special: it resolves further names.
            if cmd.name == "help" {
                return Err(help_subcommand_error(cmd, &path, bin_name, token));
            }
            return Err(invalid_subcommand(
                token,
                &aliases,
                full_usage(cmd, bin_name, &path_names(&path)),
            ));
        }
        if cmd.name == "help" {
            return Err(help_subcommand_error(cmd, &path, bin_name, token));
        }
        push_positional(cmd, &mut positionals, &mut positional_idx, token)?;
    }

    if cmd.name == "help" {
        // Resolve the requested subcommand chain.
        let mut target: &'static Cmd = &ROOT;
        let mut tpath: Vec<&'static Cmd> = Vec::new();
        for name in &positionals {
            match target.find_sub(name) {
                Some(c) => {
                    target = c;
                    tpath.push(c);
                }
                None => {
                    if target.name == "help" {
                        target = &crate::cli::HELP_CMD;
                    }
                    return Err(ClapError {
                        message: format!("unrecognized subcommand '{}'", name),
                        detail: None,
                        tip: None,
                        usage: Some(full_usage(target, bin_name, &path_names(&tpath))),
                    });
                }
            }
        }
        if positionals.is_empty() {
            return Ok(Outcome::Help {
                long: true,
                cmd: &ROOT,
                path: Vec::new(),
            });
        }
        return Ok(Outcome::Help {
            long: true,
            cmd: target,
            path: tpath,
        });
    }

    // A required subcommand that is missing prints the help to stderr.
    if cmd.sub_required {
        return Err(ClapError {
            message: String::new(),
            detail: None,
            tip: None,
            usage: None,
        });
    }

    // Missing required positionals
    let mut missing: Vec<String> = Vec::new();
    for p in cmd.positionals {
        if p.required {
            let provided = if p.multi {
                positionals.len() > positional_idx
            } else {
                positional_idx > 0
            };
            if !provided {
                missing.push(p.usage());
            }
        }
    }
    if !missing.is_empty() {
        return Err(ClapError {
            message: "the following required arguments were not provided:".to_string(),
            detail: Some(
                missing
                    .iter()
                    .map(|m| format!("  {}", m))
                    .collect::<Vec<_>>()
                    .join("\n"),
            ),
            tip: None,
            usage: Some(smart_usage(cmd, bin_name, &path_names(&path), &used)),
        });
    }

    Ok(Outcome::Matches(Box::new(Matches {
        path,
        values,
        positionals,
    })))
}

fn path_names(path: &[&'static Cmd]) -> Vec<&str> {
    path.iter().map(|c| c.name).collect()
}

fn store(
    values: &mut Vec<(&'static Arg, Vec<String>)>,
    arg: &'static Arg,
    value: String,
    used: &mut Vec<String>,
) {
    if let Some((_, v)) = values.iter_mut().find(|(a, _)| a.id == arg.id) {
        v.push(value);
        return;
    }
    used.push(arg.usage());
    values.push((arg, vec![value]));
}

fn value_required(arg: &Arg) -> ClapError {
    let detail = spec_vals(arg).first().cloned();
    ClapError {
        message: format!(
            "a value is required for '{}' but none was supplied",
            arg.usage()
        ),
        detail,
        tip: None,
        usage: None,
    }
}

fn unexpected_argument(
    cmd: &'static Cmd,
    token: &str,
    bin_name: &str,
    path: &[&'static Cmd],
    positional_hint: bool,
) -> ClapError {
    let tip = if positional_hint {
        Some(format!(
            "to pass '{}' as a value, use '-- {}'",
            token, token
        ))
    } else {
        None
    };
    ClapError {
        message: format!("unexpected argument '{}' found", token),
        detail: None,
        tip,
        usage: Some(full_usage(cmd, bin_name, &path_names(path))),
    }
}

fn help_subcommand_error(
    cmd: &'static Cmd,
    path: &[&'static Cmd],
    bin_name: &str,
    token: &str,
) -> ClapError {
    ClapError {
        message: format!("unrecognized subcommand '{}'", token),
        detail: None,
        tip: None,
        usage: Some(full_usage(cmd, bin_name, &path_names(path))),
    }
}

fn push_positional(
    cmd: &'static Cmd,
    positionals: &mut Vec<String>,
    idx: &mut usize,
    token: &str,
) -> Result<(), ClapError> {
    if *idx >= cmd.positionals.len() {
        // The last positional may be variadic
        if let Some(last) = cmd.positionals.last() {
            if last.multi {
                positionals.push(token.to_string());
                return Ok(());
            }
        }
        return Err(ClapError {
            message: format!("unexpected argument '{}' found", token),
            detail: None,
            tip: None,
            usage: None,
        });
    }
    let p = &cmd.positionals[*idx];
    positionals.push(token.to_string());
    if !p.multi {
        *idx += 1;
    }
    Ok(())
}

fn validate_value(arg: &'static Arg, value: &str) -> Result<(), ClapError> {
    match arg.id {
        "signal" => {
            if crate::signal::parse(value).is_none() {
                return Err(invalid_value(value, arg, "Matching variant not found", None));
            }
        }
        "status" => {
            if !matches!(value, "queued" | "running" | "success" | "done") {
                return Err(invalid_value(value, arg, "Matching variant not found", None));
            }
        }
        "delay" => {
            if crate::delay::parse(value).is_none() {
                return Err(invalid_value(
                    value,
                    arg,
                    "could not parse as seconds or date expression",
                    None,
                ));
            }
        }
        "lines" | "priority" | "parallel" | "task_ids" | "TASK_IDS" | "TASK_ID"
        | "TASK_ID_1" | "TASK_ID_2" | "after" | "PARALLEL_TASKS" => {
            if let Err(e) = crate::nums::parse_number(arg.id, value) {
                return Err(invalid_value(value, arg, &e, None));
            }
        }
        "color" | "SHELL" => {
            if !arg.possible.contains(&value) {
                return Err(invalid_value(value, arg, "", None));
            }
        }
        _ => {}
    }
    Ok(())
}

pub fn missing_subcommand_help(
    cmd: &'static Cmd,
    bin_name: &str,
    path: &[&'static Cmd],
    term_w: usize,
) -> String {
    crate::help::render_help(cmd, bin_name, &path_names(path), term_w, false)
}

pub fn value_width(_s: &str) -> usize {
    0
}

pub fn _unused(_s: &str) -> usize {
    width(_s)
}
