//! Number parsing that mirrors the error messages of the original binary.

pub enum NumKind {
    Usize,
    I32,
}

pub fn kind_of(id: &str) -> NumKind {
    match id {
        "priority" => NumKind::I32,
        _ => NumKind::Usize,
    }
}

/// Parse a number and return the error message of the original program.
pub fn parse_number(id: &str, value: &str) -> Result<i128, String> {
    match kind_of(id) {
        NumKind::I32 => parse_i32(value),
        NumKind::Usize => parse_usize(value),
    }
}

fn parse_usize(value: &str) -> Result<i128, String> {
    if value.is_empty() {
        return Err("cannot parse integer from empty string".to_string());
    }
    let (digits, negative) = if let Some(rest) = value.strip_prefix('+') {
        (rest, false)
    } else if let Some(rest) = value.strip_prefix('-') {
        (rest, true)
    } else {
        (value, false)
    };
    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return Err("invalid digit found in string".to_string());
    }
    // value is parsed as i64 first by the argument parser of the original
    match parse_i64_str(value) {
        Ok(v) => {
            if v < 0 {
                Err("invalid digit found in string".to_string())
            } else {
                Ok(v as i128)
            }
        }
        Err(e) => Err(e),
    }
    .map_err(|e: String| e)
}

fn parse_i64_str(value: &str) -> Result<i64, String> {
    if value.is_empty() {
        return Err("cannot parse integer from empty string".to_string());
    }
    let (digits, negative) = if let Some(rest) = value.strip_prefix('+') {
        (rest, false)
    } else if let Some(rest) = value.strip_prefix('-') {
        (rest, true)
    } else {
        (value, false)
    };
    if digits.is_empty() || !digits.bytes().all(|b| b.is_ascii_digit()) {
        return Err("invalid digit found in string".to_string());
    }
    let mut acc: i128 = 0;
    for b in digits.bytes() {
        acc = acc * 10 + (b - b'0') as i128;
        if acc > i64::MAX as i128 + 1 {
            return Err("number too large to fit in target type".to_string());
        }
    }
    if negative {
        acc = -acc;
    }
    if acc > i64::MAX as i128 {
        return Err("number too large to fit in target type".to_string());
    }
    if acc < i64::MIN as i128 {
        return Err("number too small to fit in target type".to_string());
    }
    Ok(acc as i64)
}

fn parse_i32(value: &str) -> Result<i128, String> {
    let v = parse_i64_str(value)?;
    if v < i32::MIN as i64 || v > i32::MAX as i64 {
        return Err(format!(
            "{} is not in -2147483648..=2147483647",
            v
        ));
    }
    Ok(v as i128)
}
