                if ampm && v > 12 {
                    return false;
                }
            }
            1 | 2 => {
                if v > 59 {
                    return false;
                }
            }
            _ => {}
        }
    }
    true
}

fn parse_date(token: &str) -> bool {
    // Y-M-D or M/D or M/D/Y
    if token.contains('-') {
        let parts: Vec<&str> = token.split('-').collect();
        if parts.len() != 3 {
            return false;
        }
        for p in parts {
            if !all_digits(p) {
                return false;
            }
        }
        let y: i64 = parts[0].parse().unwrap_or(i64::MAX);
        let m: i64 = parts[1].parse().unwrap_or(i64::MAX);
        let d: i64 = parts[2].parse().unwrap_or(i64::MAX);
        return (1..=12).contains(&m) && (1..=31).contains(&d) && y >= 0 && !(y == 0 && m == 0);
    }
    if token.contains('/') {
        let parts: Vec<&str> = token.split('/').collect();
        if parts.is_empty() || parts.len() > 3 {
            return false;
        }
        for p in parts {
            if !all_digits(p) {
                return false;
            }
        }
        let m: i64 = parts[0].parse().unwrap_or(i64::MAX);
        let d: i64 = parts[1].parse().unwrap_or(i64::MAX);
        return (1..=12).contains(&m) && (1..=31).contains(&d);
    }
    false
}

const KEYWORDS: &[&str] = &["now", "today", "tomorrow", "yesterday", "midnight"];

/// Returns `Some(())` when the value is accepted.
pub fn parse(input: &str) -> Option<()> {
    let s = input.trim();
    if s.is_empty() {
        return None;
    }
    // plain number of seconds
    let (sign, digits) = match s.as_bytes()[0] {
        b'+' => (1i64, &s[1..]),
        b'-' => (-1i64, &s[1..]),
        _ => (1i64, s),
    };
    if all_digits(digits) {
        return Some(());
    }
    if sign < 0 {
        return None;
    }

    let tokens: Vec<&str> = s.split_whitespace().collect();
    // duration: `<number> <unit>` or `<number><unit>`
    if tokens.len() == 1 {
        let t = tokens[0];
        let split = t.find(|c: char| !c.is_ascii_digit()).unwrap_or(t.len());
        let (num, unit) = t.split_at(split);
        if num.is_empty() {
            if all_alpha(unit) && is_unit(unit) {
                return Some(());
            }
        } else if all_alpha(unit) && is_unit(unit) {
            return Some(());
        }
    } else if tokens.len() == 2 && all_digits(tokens[0]) && all_alpha(tokens[1]) && is_unit(tokens[1])
    {
        return Some(());
    }

    // "next"/"last" + unit
    if tokens.len() == 2
        && matches!(tokens[0], "next" | "last")
        && (is_unit(tokens[1]) || is_weekday(tokens[1]))
    {
        return Some(());
    }

    // weekday, optionally with a time
    if tokens.len() == 1 && is_weekday(tokens[0]) {
        return Some(());
    }
    if tokens.len() == 2 && is_weekday(tokens[0]) && parse_time(tokens[1]) {
        return Some(());
    }

    // date, optionally with a time
    if tokens.len() == 1 && parse_date(tokens[0]) {
        return Some(());
    }
    if tokens.len() == 2 && parse_date(tokens[0]) && parse_time(tokens[1]) {
        return Some(());
    }
    if tokens.len() == 1 && tokens[0].contains('T') {
        let parts: Vec<&str> = tokens[0].split('T').collect();
        if parts.len() == 2 && parse_date(parts[0]) && parse_time(parts[1]) {
            return Some(());
        }
    }

    // time of day
    if tokens.len() == 1 && parse_time(tokens[0]) {
        return Some(());
    }

    if tokens.len() == 1 && KEYWORDS.contains(&tokens[0]) {
        return Some(());
    }

    // `<day offset> <time>`
    if tokens.len() == 2 {
        let split = tokens[0].find(|c: char| !c.is_ascii_digit()).unwrap_or(0);
        if split > 0
            && split == tokens[0].len()
            && is_unit(tokens[0][split..].trim())
        {
            return Some(());
        }
        if all_digits(tokens[0]) && is_unit(tokens[1]) {
            return Some(());
        }
        if all_alpha(tokens[0]) && is_unit(tokens[0]) && parse_time(tokens[1]) {
            return Some(());
        }
    }

    None
}
