//! A small reimplementation of the error reporting that the original program
//! uses (colored, numbered error chain plus a source location).

use std::fmt;

pub struct Report {
    /// Chain of messages, outermost first.
    pub chain: Vec<String>,
    pub location: Option<(&'static str, u32)>,
}

impl Report {
    pub fn new(chain: Vec<String>, location: (&'static str, u32)) -> Self {
        Report {
            chain,
            location: Some(location),
        }
    }

    pub fn render(&self) -> String {
        let mut out = String::from("Error: \n");
        for (i, msg) in self.chain.iter().enumerate() {
            let mut lines = msg.split('\n');
            let first = lines.next().unwrap_or("");
            out.push_str(&format!("   {}: \x1b[91m{}", i, first));
            for line in lines {
                out.push('\n');
                out.push_str("      ");
                out.push_str(line);
            }
            if i + 1 == self.chain.len() {
                out.push_str("\x1b[0m");
            }
            out.push('\n');
        }
        out.push('\n');
        if let Some((file, line)) = self.location {
            out.push_str("Location:\n");
            out.push_str(&format!("   \x1b[35m{}\x1b[0m:\x1b[35m{}\x1b[0m\n", file, line));
            out.push('\n');
        }
        out.push_str("Backtrace omitted. Run with RUST_BACKTRACE=1 environment variable to display it.\n");
        out.push_str("Run with RUST_BACKTRACE=full to include source snippets.\n");
        out
    }
}

impl fmt::Display for Report {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.render())
    }
}

pub type Result<T> = std::result::Result<T, Report>;

