//! Minimal tracing-like logging that matches the output of the original
//! program.

use std::io::Write;
use std::time::{SystemTime, UNIX_EPOCH};

fn ansi_enabled() -> bool {
    std::env::var("NO_COLOR").map(|v| v.is_empty()).unwrap_or(true)
}

/// `HH:MM:SS` in UTC.
fn timestamp() -> String {
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_secs())
        .unwrap_or(0);
    let day = secs / 86400;
    let rem = secs % 86400;
    let (h, m, s) = (rem / 3600, (rem % 3600) / 60, rem % 60);
    let _ = day;
    format!("{:02}:{:02}:{:02}", h, m, s)
}

fn dim(s: &str) -> String {
    if ansi_enabled() {
        format!("\x1b[2m{}\x1b[0m", s)
    } else {
        s.to_string()
    }
}

fn green(s: &str) -> String {
    if ansi_enabled() {
        format!("\x1b[32m{}\x1b[0m", s)
    } else {
        s.to_string()
    }
}

/// Emit an INFO level event in the "compact" format.
pub fn info(target: &str, message: &str) {
    let mut out = String::new();
    out.push_str(&dim(&timestamp()));
    out.push(' ');
    out.push_str(&green(" INFO"));
