    out.push_str(&dim(target));
    out.push_str(&dim(":"));
    out.push(' ');
    out.push_str(message);
    out.push('\n');
    let stderr = std::io::stderr();
    let mut lock = stderr.lock();
    let _ = lock.write_all(out.as_bytes());
    let _ = lock.flush();
}

/// Emit an INFO level event in the "pretty" format (verbosity >= 4).
pub fn info_pretty(target: &str, message: &str, file: &str, line: u32) {
    let mut out = String::new();
    if ansi_enabled() {
        out.push_str(&format!(
            "  \x1b[2m{}\x1b[0m \x1b[32m INFO\x1b[0m \x1b[1;32m{}\x1b[0m\x1b[32m: \x1b[32m{}\x1b[0m\n",
            timestamp(),
            target,
            message
        ));
        out.push_str(&format!(
            "    \x1b[2;3mat\x1b[0m {}:{} \x1b[2;3mon\x1b[0m main\n\n",
            file, line
