//! A small YAML subset parser.
//!
//! Only the constructs that can appear in a Pueue configuration file are
//! supported.  The error messages mimic the ones of the YAML library that the
//! original program uses.

#[derive(Debug, Clone, PartialEq)]
pub enum Value {
    Null,
    Bool(bool),
    Int(i64),
    Float(f64),
    Str(String),
    Seq(Vec<Node>),
    Map(Vec<(String, Node)>),
}

#[derive(Debug, Clone, PartialEq)]
pub struct Node {
    pub value: Value,
    pub line: usize,
    pub col: usize,
}

impl Node {
    fn new(value: Value, line: usize, col: usize) -> Self {
        Node { value, line, col }
    }
}

/// A serde style "unexpected" description used in error messages.
pub fn unexpected(node: &Node) -> String {
    match &node.value {
        Value::Null => "unit value".to_string(),
        Value::Bool(b) => format!("boolean `{}`", b),
        Value::Int(i) => format!("integer `{}`", i),
        Value::Float(f) => format!("floating point `{}`", with_decimal(*f)),
        Value::Str(s) => format!("string {:?}", s),
        Value::Seq(_) => "sequence".to_string(),
        Value::Map(_) => "map".to_string(),
    }
}

/// serde renders floats with a decimal point.
fn with_decimal(f: f64) -> String {
    if f.is_nan() {
        return "NaN".to_string();
    }
    if f.is_infinite() {
        return if f > 0.0 { "inf".to_string() } else { "-inf".to_string() };
    }
    let s = format!("{}", f);
    if s.contains('.') || s.contains('e') || s.contains('E') {
        s
    } else {
        format!("{}.0", s)
    }
}

pub struct ParseError {
    pub message: String,
}

struct Line {
    indent: usize,
    text: String,
    number: usize,
}

fn split_lines(content: &str) -> Vec<Line> {
    let mut out = Vec::new();
    for (i, raw) in content.split('\n').enumerate() {
        let raw = raw.trim_end_matches('\r');
        let trimmed = raw.trim_start_matches(' ');
        let indent = raw.len() - trimmed.len();
        // comments and empty lines are skipped, but keep them for line numbers
        if trimmed.is_empty() || trimmed.starts_with('#') {
            continue;
        }
        out.push(Line {
            indent,
            text: trimmed.to_string(),
            number: i + 1,
        });
    }
    out
}

/// Column (1 based) of the value inside the original line.
fn value_column(raw_line: &str, key_len: usize) -> usize {
    // raw_line is the original line; the value starts after "key:" and spaces
    let _ = raw_line;
    key_len
}

pub fn parse(content: &str) -> Result<Node, ParseError> {
    // Only the first document is used.
    let mut body = String::new();
    let mut started = false;
    let mut offset = 0usize;
    let mut line_no = 0usize;
    for raw in content.split_inclusive('\n') {
        line_no += 1;
        let t = raw.trim();
        if !started {
            if t == "---" || t.starts_with("--- ") {
                started = true;
                offset = line_no;
                continue;
            }
            if t.starts_with('%') {
                offset = line_no;
                continue;
            }
            if t.is_empty() || t.starts_with('#') {
                offset = line_no;
                continue;
            }
            started = true;
        }
        body.push_str(raw);
    }
    if !started {
        return Ok(Node::new(Value::Null, 1, 1));
    }
    let lines = split_lines(&body);
    if lines.is_empty() {
        return Ok(Node::new(Value::Null, offset + 1, 1));
    }
    let mut idx = 0usize;
    let node = parse_block(&lines, &mut idx, 0, offset)?;
    Ok(node)
}

fn parse_block(
    lines: &[Line],
    idx: &mut usize,
    min_indent: usize,
    offset: usize,
) -> Result<Node, ParseError> {
    if *idx >= lines.len() {
        return Ok(Node::new(Value::Null, offset + 1, 1));
    }
    let first = &lines[*idx];
    if first.indent < min_indent {
        return Ok(Node::new(Value::Null, first.number, first.indent + 1));
    }
    if first.text == "-" || first.text.starts_with("- ") {
        return parse_seq(lines, idx, offset);
    }
    parse_map(lines, idx, offset)
}

fn parse_seq(lines: &[Line], idx: &mut usize, offset: usize) -> Result<Node, ParseError> {
    let indent = lines[*idx].indent;
    let start_line = lines[*idx].number;
    let mut items = Vec::new();
    while *idx < lines.len() {
        let line = &lines[*idx];
        if line.indent != indent || !(line.text == "-" || line.text.starts_with("- ")) {
            break;
        }
        let rest = line.text[1..].trim_start();
        let col = line.indent + (line.text.len() - rest.len()) + 1;
        if rest.is_empty() {
            *idx += 1;
            let child = parse_block(lines, idx, indent + 1, offset)?;
            items.push(child);
        } else if let Some(p) = find_colon(rest) {
            // inline mapping inside a sequence item
            let key = unquote(&rest[..p]);
            let value_part = rest[p + 1..].trim_start();
            let vcol = col + p + 1 + (rest[p + 1..].len() - rest[p + 1..].trim_start().len());
            let node = if value_part.is_empty() {
                *idx += 1;
                parse_block(lines, idx, indent + 1, offset)?
            } else {
                *idx += 1;
                parse_inline(value_part, line.number, vcol, offset)?
            };
            items.push(Node::new(
                Value::Map(vec![(key, node)]),
                line.number,
                col,
            ));
        } else {
            items.push(parse_inline(rest, line.number, col, offset)?);
            *idx += 1;
        }
    }
    Ok(Node::new(Value::Seq(items), start_line, indent + 1))
}

fn parse_map(lines: &[Line], idx: &mut usize, offset: usize) -> Result<Node, ParseError> {
    let indent = lines[*idx].indent;
    let start_line = lines[*idx].number;
    let mut entries: Vec<(String, Node)> = Vec::new();
    while *idx < lines.len() {
        let line = &lines[*idx];
        if line.indent != indent {
            break;
        }
        if line.text.starts_with("- ") || line.text == "-" {
            break;
        }
        let colon = match find_colon(&line.text) {
            Some(c) => c,
            None => {
                return Err(ParseError {
                    message: format!(
                        "could not find expected ':' at line {} column {}",
                        line.number,
                        line.indent + line.text.len() + 1
                    ),
                })
            }
        };
        let key = unquote(&line.text[..colon]);
        let rest = line.text[colon + 1..].trim_start();
        let vcol = line.indent
            + colon
            + 2
            + (line.text[colon + 1..].len() - line.text[colon + 1..].trim_start().len());
        if rest.is_empty() {
            *idx += 1;
            let child = if *idx < lines.len() && lines[*idx].indent > indent {
                parse_block(lines, idx, indent + 1, offset)?
            } else {
                Node::new(Value::Null, line.number, vcol)
            };
            entries.push((key, child));
        } else {
            let node = parse_inline(rest, line.number, vcol, offset)?;
            *idx += 1;
            entries.push((key, node));
        }
    }
    Ok(Node::new(Value::Map(entries), start_line, indent + 1))
}

/// Find the colon that separates a key from its value.
fn find_colon(text: &str) -> Option<usize> {
    let bytes = text.as_bytes();
    let mut in_single = false;
    let mut in_double = false;
    let mut depth = 0i32;
    let mut i = 0;
    while i < bytes.len() {
        match bytes[i] {
            b'\'' if !in_double => in_single = !in_single,
            b'"' if !in_single => in_double = !in_double,
            b'[' | b'{' if !in_single && !in_double => depth += 1,
            b']' | b'}' if !in_single && !in_double => depth -= 1,
            b':' if !in_single && !in_double && depth == 0 => {
                if i + 1 == bytes.len() || bytes[i + 1] == b' ' {
                    return Some(i);
                }
            }
            _ => {}
        }
        i += 1;
    }
    None
}

fn unquote(text: &str) -> String {
    let t = text.trim();
    if t.len() >= 2 && t.starts_with('\'') && t.ends_with('\'') {
        return t[1..t.len() - 1].replace("''", "'");
    }
    if t.len() >= 2 && t.starts_with('"') && t.ends_with('"') {
        return unescape_double(&t[1..t.len() - 1]);
    }
    // strip a trailing comment
    let mut out = String::new();
    let mut in_single = false;
    let mut in_double = false;
    for (i, c) in t.char_indices() {
        match c {
            '\'' if !in_double => in_single = !in_single,
            '"' if !in_single => in_double = !in_double,
            '#' if !in_single && !in_double && (i == 0 || t.as_bytes()[i - 1] == b' ') => break,
            _ => {}
        }
        out.push(c);
    }
    out.trim_end().to_string()
}

fn unescape_double(s: &str) -> String {
    let mut out = String::new();
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c != '\\' {
            out.push(c);
            continue;
        }
        match chars.next() {
            Some('n') => out.push('\n'),
            Some('t') => out.push('\t'),
            Some('r') => out.push('\r'),
            Some('0') => out.push('\0'),
            Some('\\') => out.push('\\'),
            Some('"') => out.push('"'),
            Some(other) => {
                out.push('\\');
                out.push(other);
            }
            None => out.push('\\'),
        }
    }
    out
}

fn parse_inline(text: &str, line: usize, col: usize, _offset: usize) -> Result<Node, ParseError> {
    let t = text.trim();
    if t.starts_with('[') {
        if !t.ends_with(']') {
            return Err(ParseError {
                message: format!(
                    "found unexpected end of stream at line {} column {}, while parsing a flow sequence",
                    line + 1,
                    1
                ),
            });
        }
        let inner = &t[1..t.len() - 1];
        let mut items = Vec::new();
        for part in split_flow(inner) {
            let part = part.trim();
            if part.is_empty() {
                continue;
            }
            items.push(parse_inline(part, line, col, _offset)?);
        }
        return Ok(Node::new(Value::Seq(items), line, col));
    }
    if t.starts_with('{') {
        if !t.ends_with('}') {
            return Err(ParseError {
                message: format!(
                    "found unexpected end of stream at line {} column {}, while parsing a flow mapping",
                    line + 1,
                    1
                ),
            });
        }
        let inner = &t[1..t.len() - 1];
        let mut entries = Vec::new();
        for part in split_flow(inner) {
            let part = part.trim();
            if part.is_empty() {
                continue;
            }
            match find_colon(part) {
                Some(p) => {
                    let key = unquote(&part[..p]);
                    let value = parse_inline(part[p + 1..].trim(), line, col, _offset)?;
                    entries.push((key, value));
                }
                None => {
                    let key = unquote(part);
                    entries.push((key, Node::new(Value::Null, line, col)));
                }
            }
        }
        return Ok(Node::new(Value::Map(entries), line, col));
    }
    if t.starts_with('"') {
        if t.len() < 2 || !t.ends_with('"') {
            return Err(ParseError {
                message: format!(
                    "found unexpected end of stream at line {} column 1, while scanning a quoted scalar",
                    line + 1
                ),
            });
        }
        return Ok(Node::new(
            Value::Str(unescape_double(&t[1..t.len() - 1])),
            line,
            col,
        ));
    }
    if t.starts_with('\'') {
        if t.len() < 2 || !t.ends_with('\'') {
            return Err(ParseError {
                message: format!(
                    "found unexpected end of stream at line {} column 1, while scanning a quoted scalar",
                    line + 1
                ),
            });
        }
        return Ok(Node::new(
            Value::Str(t[1..t.len() - 1].replace("''", "'")),
            line,
            col,
        ));
    }
    Ok(Node::new(scalar(t), line, col))
}

fn split_flow(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut depth = 0i32;
    let mut cur = String::new();
    let mut in_single = false;
    let mut in_double = false;
    for c in s.chars() {
        match c {
            '\'' if !in_double => {
                in_single = !in_single;
                cur.push(c);
            }
            '"' if !in_single => {
                in_double = !in_double;
                cur.push(c);
            }
            '[' | '{' if !in_single && !in_double => {
                depth += 1;
                cur.push(c);
            }
            ']' | '}' if !in_single && !in_double => {
                depth -= 1;
                cur.push(c);
            }
            ',' if !in_single && !in_double && depth == 0 => {
                out.push(cur.clone());
                cur.clear();
            }
            _ => cur.push(c),
        }
    }
    if !cur.trim().is_empty() {
        out.push(cur);
    }
    out
}

/// Determine the type of a plain scalar.
pub fn scalar(text: &str) -> Value {
    let t = text.trim();
    if t.is_empty() {
        return Value::Null;
    }
    match t {
        "~" | "null" | "Null" | "NULL" => return Value::Null,
        "true" | "True" | "TRUE" => return Value::Bool(true),
        "false" | "False" | "FALSE" => return Value::Bool(false),
        ".inf" | ".Inf" | ".INF" | "+.inf" | "+.Inf" | "+.INF" => return Value::Float(f64::INFINITY),
        "-.inf" | "-.Inf" | "-.INF" => return Value::Float(f64::NEG_INFINITY),
        ".nan" | ".NaN" | ".NAN" => return Value::Float(f64::NAN),
        _ => {}
    }
    if let Some(v) = parse_int(t) {
        return Value::Int(v);
    }
    if let Some(v) = parse_float(t) {
        return Value::Float(v);
    }
    Value::Str(t.to_string())
}

fn parse_int(t: &str) -> Option<i64> {
    let (sign, rest) = if let Some(r) = t.strip_prefix('-') {
        (-1i64, r)
    } else if let Some(r) = t.strip_prefix('+') {
        (1i64, r)
    } else {
        (1i64, t)
    };
    if rest.is_empty() {
        return None;
    }
    if let Some(hex) = rest.strip_prefix("0x") {
        if !hex.is_empty() && hex.bytes().all(|b| b.is_ascii_hexdigit()) {
            return i64::from_str_radix(hex, 16).ok().map(|v| sign * v);
        }
        return None;
    }
    if let Some(oct) = rest.strip_prefix("0o") {
        if !oct.is_empty() && oct.bytes().all(|b| (b'0'..=b'7').contains(&b)) {
            return i64::from_str_radix(oct, 8).ok().map(|v| sign * v);
        }
        return None;
    }
    if let Some(bin) = rest.strip_prefix("0b") {
        if !bin.is_empty() && bin.bytes().all(|b| b == b'0' || b == b'1') {
            return i64::from_str_radix(bin, 2).ok().map(|v| sign * v);
        }
        return None;
    }
    if rest.bytes().all(|b| b.is_ascii_digit()) {
        // Leading zeros are not allowed (YAML 1.2 core schema)
        if rest.len() > 1 && rest.starts_with('0') {
            return None;
        }
        return rest.parse::<i64>().ok().map(|v| sign * v);
    }
    None
}

fn parse_float(t: &str) -> Option<f64> {
    if t.is_empty() {
        return None;
    }
    // A float needs a '.', 'e'/'E' or an inf/nan marker; plain integers were
    // already handled.
    if !t.contains('.') && !t.contains('e') && !t.contains('E') {
        return None;
    }
    t.parse::<f64>().ok()
}
