    if t.starts_with('[') {
        if !t.ends_with(']') {
            return Err(ParseError {
                message: format!(
                    "found unexpected end of stream at line {} column {}, while parsing a flow sequence",
                    line + 1,
                    1
                ),
            });
        }
        let inner = &t[1..t.len() - 1];
        let mut items = Vec::new();
        for part in split_flow(inner) {
            let part = part.trim();
            if part.is_empty() {
                continue;
            }
            items.push(parse_inline(part, line, col, _offset)?);
        }
        return Ok(Node::new(Value::Seq(items), line, col));
    }
    if t.starts_with('{') {
        if !t.ends_with('}') {
            return Err(ParseError {
                message: format!(
                    "found unexpected end of stream at line {} column {}, while parsing a flow mapping",
                    line + 1,
                    1
                ),
            });
        }
        let inner = &t[1..t.len() - 1];
        let mut entries = Vec::new();
        for part in split_flow(inner) {
            let part = part.trim();
            if part.is_empty() {
                continue;
            }
            match find_colon(part) {
                Some(p) => {
                    let key = unquote(&part[..p]);
                    let value = parse_inline(part[p + 1..].trim(), line, col, _offset)?;
                    entries.push((key, value));
                }
                None => {
                    let key = unquote(part);
                    entries.push((key, Node::new(Value::Null, line, col)));
                }
            }
        }
        return Ok(Node::new(Value::Map(entries), line, col));
    }
    if t.starts_with('"') {
        if t.len() < 2 || !t.ends_with('"') {
            return Err(ParseError {
                message: format!(
                    "found unexpected end of stream at line {} column 1, while scanning a quoted scalar",
                    line + 1
                ),
            });
        }
        return Ok(Node::new(
            Value::Str(unescape_double(&t[1..t.len() - 1])),
            line,
            col,
        ));
    }
    if t.starts_with('\'') {
        if t.len() < 2 || !t.ends_with('\'') {
            return Err(ParseError {
                message: format!(
                    "found unexpected end of stream at line {} column 1, while scanning a quoted scalar",
                    line + 1
                ),
            });
        }
        return Ok(Node::new(
            Value::Str(t[1..t.len() - 1].replace("''", "'")),
            line,
            col,
        ));
    }
    Ok(Node::new(scalar(t), line, col))
}

fn split_flow(s: &str) -> Vec<String> {
    let mut out = Vec::new();
    let mut depth = 0i32;
    let mut cur = String::new();
    let mut in_single = false;
    let mut in_double = false;
    for c in s.chars() {
        match c {
            '\'' if !in_double => {
                in_single = !in_single;
                cur.push(c);
            }
            '"' if !in_single => {
                in_double = !in_double;
                cur.push(c);
            }
            '[' | '{' if !in_single && !in_double => {
                depth += 1;
                cur.push(c);
            }
            ']' | '}' if !in_single && !in_double => {
                depth -= 1;
                cur.push(c);
            }
            ',' if !in_single && !in_double && depth == 0 => {
                out.push(cur.clone());
                cur.clear();
            }
            _ => cur.push(c),
        }
    }
    if !cur.trim().is_empty() {
        out.push(cur);
    }
    out
}

/// Determine the type of a plain scalar.
pub fn scalar(text: &str) -> Value {
    let t = text.trim();
    if t.is_empty() {
        return Value::Null;
    }
    match t {
        "~" | "null" | "Null" | "NULL" => return Value::Null,
        "true" | "True" | "TRUE" => return Value::Bool(true),
        "false" | "False" | "FALSE" => return Value::Bool(false),
        ".inf" | ".Inf" | ".INF" | "+.inf" | "+.Inf" | "+.INF" => return Value::Float(f64::INFINITY),
        "-.inf" | "-.Inf" | "-.INF" => return Value::Float(f64::NEG_INFINITY),
        ".nan" | ".NaN" | ".NAN" => return Value::Float(f64::NAN),
        _ => {}
    }
    if let Some(v) = parse_int(t) {
        return Value::Int(v);
    }
    if let Some(v) = parse_float(t) {
        return Value::Float(v);
    }
    Value::Str(t.to_string())
}

fn parse_int(t: &str) -> Option<i64> {
    let (sign, rest) = if let Some(r) = t.strip_prefix('-') {
        (-1i64, r)
    } else if let Some(r) = t.strip_prefix('+') {
        (1i64, r)
    } else {
        (1i64, t)
    };
    if rest.is_empty() {
        return None;
    }
    if let Some(hex) = rest.strip_prefix("0x") {
        if !hex.is_empty() && hex.bytes().all(|b| b.is_ascii_hexdigit()) {
            return i64::from_str_radix(hex, 16).ok().map(|v| sign * v);
        }
        return None;
    }
    if let Some(oct) = rest.strip_prefix("0o") {
        if !oct.is_empty() && oct.bytes().all(|b| (b'0'..=b'7').contains(&b)) {
            return i64::from_str_radix(oct, 8).ok().map(|v| sign * v);
        }
        return None;
    }
    if let Some(bin) = rest.strip_prefix("0b") {
        if !bin.is_empty() && bin.bytes().all(|b| b == b'0' || b == b'1') {
            return i64::from_str_radix(bin, 2).ok().map(|v| sign * v);
        }
        return None;
    }
    if rest.bytes().all(|b| b.is_ascii_digit()) {
        // Leading zeros are not allowed (YAML 1.2 core schema)
        if rest.len() > 1 && rest.starts_with('0') {
            return None;
        }
        return rest.parse::<i64>().ok().map(|v| sign * v);
    }
    None
}

fn parse_float(t: &str) -> Option<f64> {
    if t.is_empty() {
        return None;
    }
    // A float needs a '.', 'e'/'E' or an inf/nan marker; plain integers were
    // already handled.
    if !t.contains('.') && !t.contains('e') && !t.contains('E') {
        return None;
    }
    t.parse::<f64>().ok()
}
