//! Configuration handling.

use crate::eyre::{context, Report, Result, LOC_CONFIG_READ, LOC_NO_CONFIG, LOC_PROFILE};
use crate::logging;
use crate::yaml::{self, Node, Value};

pub const TARGET: &str = "pueue_lib::settings";

#[derive(Clone, Debug)]
pub struct Settings {
    pub daemon: Daemon,
    pub client: Client,
}

#[derive(Clone, Debug, Default)]
pub struct Daemon {
    pub pause_group_on_failure: bool,
    pub pause_all_on_failure: bool,
    pub callback: String,
}

#[derive(Clone, Debug, Default)]
pub struct Client {
    pub restart_in_place: bool,
    pub read_local_logs: bool,
    pub show_confirmation_questions: bool,
    pub show_expanded_aliases: bool,
    pub dark_mode: bool,
    pub status_time_format: String,
}

impl Default for Settings {
    fn default() -> Self {
        Settings {
            daemon: Daemon::default(),
            client: Client::default(),
        }
    }
}

/// XDG style config directory.
pub fn config_dir() -> Option<std::path::PathBuf> {
    if let Some(dir) = std::env::var_os("XDG_CONFIG_HOME") {
        let path = std::path::PathBuf::from(dir);
        if path.is_absolute() {
            return Some(path.join("pueue"));
        }
