use crate::eyre::{context, Report, Result, LOC_CONFIG_READ, LOC_NO_CONFIG, LOC_PROFILE};
use crate::logging;
use crate::yaml::{self, Node, Value};

pub const TARGET: &str = "pueue_lib::settings";

#[derive(Clone, Debug)]
pub struct Settings {
    pub daemon: Daemon,
    pub client: Client,
}

#[derive(Clone, Debug, Default)]
pub struct Daemon {
    pub pause_group_on_failure: bool,
    pub pause_all_on_failure: bool,
    pub callback: String,
}

#[derive(Clone, Debug, Default)]
pub struct Client {
    pub restart_in_place: bool,
    pub read_local_logs: bool,
    pub show_confirmation_questions: bool,
    pub show_expanded_aliases: bool,
    pub dark_mode: bool,
    pub status_time_format: String,
}

impl Default for Settings {
    fn default() -> Self {
        Settings {
            daemon: Daemon::default(),
            client: Client::default(),
        }
    }
}

/// XDG style config directory.
pub fn config_dir() -> Option<std::path::PathBuf> {
    if let Some(dir) = std::env::var_os("XDG_CONFIG_HOME") {
        let path = std::path::PathBuf::from(dir);
        if path.is_absolute() {
            return Some(path.join("pueue"));
        }
    }
    home_dir().map(|h| h.join(".config").join("pueue"))
}

pub fn home_dir() -> Option<std::path::PathBuf> {
    if let Some(home) = std::env::var_os("HOME") {
        let path = std::path::PathBuf::from(home);
        if path.is_absolute() {
            return Some(path);
        }
    }
    passwd_home()
}

/// Fall back to the user database when `$HOME` is not usable.
fn passwd_home() -> Option<std::path::PathBuf> {
    let uid = unsafe { libc_getuid() };
    let content = std::fs::read_to_string("/etc/passwd").ok()?;
    for line in content.lines() {
        let fields: Vec<&str> = line.split(':').collect();
        if fields.len() >= 6 {
            if let Ok(u) = fields[2].parse::<u32>() {
                if u == uid {
                    return Some(std::path::PathBuf::from(fields[5]));
                }
            }
        }
    }
    None
}

extern "C" {
    fn getuid() -> u32;
}

unsafe fn libc_getuid() -> u32 {
    getuid()
}

/// The current user name as reported by the operating system.
pub fn user_name() -> String {
    let uid = unsafe { getuid() };
    if let Ok(content) = std::fs::read_to_string("/etc/passwd") {
        for line in content.lines() {
            let fields: Vec<&str> = line.split(':').collect();
            if fields.len() >= 6 {
                if let Ok(u) = fields[2].parse::<u32>() {
                    if u == uid {
                        return fields[0].to_string();
                    }
                }
            }
        }
    }
    "unknown".to_string()
}

/// XDG style data directory.
pub fn data_dir() -> Option<std::path::PathBuf> {
    if let Some(dir) = std::env::var_os("XDG_DATA_HOME") {
        let path = std::path::PathBuf::from(dir);
        if path.is_absolute() {
            return Some(path.join("pueue"));
        }
    }
    home_dir().map(|h| h.join(".local").join("share").join("pueue"))
}

/// Candidate paths that are searched when no explicit path is given.
pub fn candidate_paths() -> Vec<std::path::PathBuf> {
    let mut out = Vec::new();
    if let Some(dir) = config_dir() {
        out.push(dir.join("pueue.yml"));
    }
    out.push(std::path::PathBuf::from("./pueue.yml"));
    out
}

fn io_message(err: &std::io::Error) -> String {
    format!("{}", err)
}

/// Read the configuration from an explicit path.
fn read_from_path(path: &std::path::Path) -> Result<String> {
    let file = std::fs::File::open(path).map_err(|err| {
        Report::new(
            vec![
                "Failed to read configuration.".to_string(),
                format!(
                    "I/O error at path {:?} while opening config file:\n{}",
                    path, err
                ),
            ],
            LOC_CONFIG_READ,
        )
    })?;
    let mut s = String::new();
    use std::io::Read;
    let mut file = file;
    file.read_to_string(&mut s)
        .map_err(|err| {
            Report::new(
                vec![
                    "Failed to read configuration.".to_string(),
                    "Error while reading configuration:".to_string(),
                    io_message(&err),
                ],
                LOC_CONFIG_READ,
            )
        })
        .map(|_| s)
}

/// Search the default locations and read the configuration.
fn read_searched(verbose: usize) -> Result<(String, bool)> {
    if verbose > 0 {
        log_settings("Parsing config files", 391, verbose);
    }
    for path in candidate_paths() {
        if verbose > 0 {
            log_settings(&format!("Checking path: {:?}", path), 396, verbose);
        }
        if path.is_file() {
            if verbose > 0 {
                log_settings(&format!("Found config file at: {:?}", path), 400, verbose);
            }
            let content = read_from_path(&path)?;
            return Ok((content, true));
        }
    }
    if verbose > 0 {
        log_settings("No config file found. Use default config.", 413, verbose);
    }
    Ok((String::new(), false))
}

fn log_settings(message: &str, line: u32, verbose: usize) {
    if verbose >= 4 {
        logging::info_pretty(TARGET, message, "pueue_lib/src/settings.rs", line);
    } else {
        logging::info(TARGET, message);
    }
}

/// Deserialize a boolean field.
fn get_bool(node: &Node, path: &str, key: &str) -> Result<Option<bool>> {
    for (k, v) in map_entries(node) {
        if k == key {
            return match &v.value {
                Value::Bool(b) => Ok(Some(*b)),
                _ => Err(type_error(path, key, v, "a boolean")),
            };
        }
    }
    Ok(None)
}

fn get_string(node: &Node, path: &str, key: &str) -> Result<Option<String>> {
    for (k, v) in map_entries(node) {
        if k == key {
            return match &v.value {
                Value::Str(s) => Ok(Some(s.clone())),
                _ => Err(type_error(path, key, v, "a string")),
            };
        }
    }
    Ok(None)
}

fn map_entries(node: &Node) -> &[(String, Node)] {
    match &node.value {
        Value::Map(m) => m,
        _ => &[],
    }
}

fn type_error(path: &str, key: &str, node: &Node, expected: &str) -> Report {
    let full = if path.is_empty() {
        key.to_string()
    } else {
        format!("{}.{}", path, key)
    };
    Report::new(
        vec![
            "Error while reading configuration:".to_string(),
            format!(
                "{}: invalid type: {}, expected {} at line {} column {}",
                full,
                yaml::unexpected(node),
                expected,
                node.line,
                node.col
            ),
        ],
        LOC_CONFIG_READ,
    )
}

fn struct_error(path: &str, node: &Node, expected: &str) -> Report {
    let msg = if path.is_empty() {
        format!(
            "invalid type: {}, expected {}",
            yaml::unexpected(node),
            expected
        )
    } else {
        format!(
            "{}: invalid type: {}, expected {} at line {} column {}",
            path,
            yaml::unexpected(node),
            expected,
            node.line,
            node.col
        )
    };
    Report::new(
        vec!["Error while reading configuration:".to_string(), msg],
        LOC_CONFIG_READ,
    )
}

fn parse_daemon(node: &Node, path: &str) -> Result<Daemon> {
    let mut daemon = Daemon::default();
    if !matches!(node.value, Value::Map(_)) {
        return Err(struct_error(path, node, "struct Daemon"));
    }
    daemon.pause_group_on_failure =
        get_bool(node, path, "pause_group_on_failure")?.unwrap_or(false);
    daemon.pause_all_on_failure = get_bool(node, path, "pause_all_on_failure")?.unwrap_or(false);
    daemon.callback = get_string(node, path, "callback")?.unwrap_or_default();
    Ok(daemon)
}

fn parse_client(node: &Node, path: &str) -> Result<Client> {
    let mut client = Client::default();
    if !matches!(node.value, Value::Map(_)) {
        return Err(struct_error(path, node, "struct Client"));
    }
    client.restart_in_place = get_bool(node, path, "restart_in_place")?.unwrap_or(false);
    client.read_local_logs = get_bool(node, path, "read_local_logs")?.unwrap_or(true);
    client.show_confirmation_questions =
        get_bool(node, path, "show_confirmation_questions")?.unwrap_or(false);
    client.show_expanded_aliases =
        get_bool(node, path, "show_expanded_aliases")?.unwrap_or(false);
    client.dark_mode = get_bool(node, path, "dark_mode")?.unwrap_or(false);
    client.status_time_format =
        get_string(node, path, "status_time_format")?.unwrap_or_default();
    Ok(client)
}

/// Parse the configuration contents.
pub fn parse_settings(content: &str) -> Result<Settings> {
    let node = match yaml::parse(content) {
        Ok(n) => n,
        Err(e) => {
            return Err(Report::new(
                vec![
                    "Failed to read configuration.".to_string(),
                    "Error while reading configuration:".to_string(),
                    e.message,
                ],
                LOC_CONFIG_READ,
            ))
        }
    };
    if !matches!(node.value, Value::Map(_)) {
        let msg = format!(
            "invalid type: {}, expected struct Settings",
            yaml::unexpected(&node)
        );
        return Err(Report::new(
            vec![
                "Failed to read configuration.".to_string(),
                "Error while reading configuration:".to_string(),
                msg,
            ],
            LOC_CONFIG_READ,
        ));
    }
    let mut settings = Settings::default();
    for (key, value) in map_entries(&node) {
        match key.as_str() {
            "daemon" => settings.daemon = parse_daemon(value, "")?,
            "client" => settings.client = parse_client(value, "")?,
            "profiles" => {
                if !matches!(value.value, Value::Map(_)) {
                    return Err(type_error("", "profiles", value, "a map"));
                }
                for (name, nested) in map_entries(value) {
                    if !matches!(nested.value, Value::Map(_)) {
                        let path = format!("profiles.{}", name);
                        return Err(struct_error(&path, nested, "struct NestedSettings"));
                    }
                    for (k, v) in map_entries(nested) {
                        match k.as_str() {
                            "daemon" => {
                                parse_daemon(v, &format!("profiles.{}", name))?;
                            }
                            "client" => {
                                parse_client(v, &format!("profiles.{}", name))?;
                            }
                            _ => {}
                        }
                    }
                }
            }
            _ => {}
        }
    }
    Ok(settings)
}

/// Load the settings, honouring the command line options.
pub fn load(
    cli_config: Option<&String>,
    profile: Option<&String>,
    verbose: usize,
) -> Result<Settings> {
    let (content, found) = match cli_config {
        Some(path) => (read_from_path(std::path::Path::new(path))?, true),
        None => match std::env::var("PUEUE_CONFIG_PATH") {
            Ok(path) if !path.is_empty() => {
                (read_from_path(std::path::Path::new(&path))?, true)
            }
            _ => read_searched(verbose)?,
        },
    };
    let mut settings = parse_settings(&content)?;
    if !found {
        // The original program refuses to continue without a config file.
        return Err(Report::new(
            vec!["Couldn't find a configuration file. Did you start the daemon yet?".to_string()],
            LOC_NO_CONFIG,
        ));
    }
    if let Some(name) = profile {
        let node = yaml::parse(&content).unwrap_or(Node::new(Value::Null, 1, 1));
        let mut found_profile = false;
        for (key, value) in map_entries(&node) {
            if key == "profiles" {
                for (pname, nested) in map_entries(value) {
                    if pname == name {
                        found_profile = true;
                        for (k, v) in map_entries(nested) {
                            match k.as_str() {
                                "daemon" => settings.daemon = parse_daemon(v, "")?,
                                "client" => settings.client = parse_client(v, "")?,
                                _ => {}
                            }
                        }
                    }
                }
            }
        }
        if !found_profile {
            return Err(Report::new(
                vec![
                    "Error while reading configuration:".to_string(),
                    format!("Couldn't find profile with name {:?}", name),
                ],
                LOC_PROFILE,
            ));
        }
    }
    Ok(settings)
}

/// Helper that adds a context to an error.
pub fn wrap(err: Report, msg: &str) -> Report {
    context(err, msg)
}
