//! Talking to the daemon.
//!
//! Without a running daemon every request fails while establishing the
//! connection, which is exactly what is reproduced here.

use std::os::unix::net::UnixStream;
use std::path::PathBuf;

use crate::eyre::{Report, Result, LOC_CLIENT_INIT, LOC_SECRET};
use crate::settings;

pub struct Client {
    pub _stream: Option<UnixStream>,
}

/// Read the shared secret from the data directory.
pub fn read_secret() -> Result<Vec<u8>> {
    let path = secret_path();
    let mut file = std::fs::File::open(&path).map_err(|err| {
        Report::new(
            vec![format!(
                "I/O error at path {:?} while opening secret file. Did you start the daemon at least once?:\n{}",
                path, err
            )],
            LOC_SECRET,
        )
    })?;
    use std::io::Read;
    let mut buf = Vec::new();
    file.read_to_end(&mut buf).map_err(|err| {
        Report::new(
            vec![format!(
                "I/O error at path {:?} while reading secret file:\n{}",
                path, err
            )],
            LOC_SECRET,
        )
    })?;
    Ok(buf)
}

pub fn secret_path() -> PathBuf {
    let mut path = settings::data_dir().unwrap_or_else(|| PathBuf::from("."));
    path.push("shared_secret");
    path
}

pub fn socket_path() -> PathBuf {
    let mut path = settings::data_dir().unwrap_or_else(|| PathBuf::from("."));
    path.push(format!("pueue_{}.socket", settings::user_name()));
    path
}

/// Establish the connection to the daemon.
pub fn connect() -> Result<Client> {
    let path = socket_path();
    let stream = UnixStream::connect(&path).map_err(|err| {
        Report::new(
            vec![
                "Failed to initialize client.".to_string(),
                "Failed to initialize stream.".to_string(),
                format!(
                    "I/O error at path {:?} while connecting to daemon. Did you start it?:\n{}",
                    path, err
                ),
            ],
            LOC_CLIENT_INIT,
        )
    })?;
    Ok(Client {
        _stream: Some(stream),
    })
}
