//! `pueue` client.

mod alias;
mod cli;
mod client;
mod complete;
mod delay;
mod eyre;
mod help;
mod logging;
mod model;
mod nums;
mod parser;
mod settings;
mod signal;
mod yaml;

use std::io::Write;

use eyre::Report;
use model::Cmd;
use parser::{ClapError, Outcome};

fn main() {
    let argv: Vec<String> = std::env::args().skip(1).collect();
    let bin_name = bin_name();

    match parser::parse(&argv, &bin_name) {
        Ok(Outcome::Version) => {
            println!("pueue {}", crate::VERSION);
        }
        Ok(Outcome::Help { long, cmd, path }) => {
            let help = help::render_help(
                cmd,
                &bin_name,
                &path_names(&path),
                term_width(),
                long,
            );
            print!("{}", help);
            let _ = std::io::stdout().flush();
        }
        Ok(Outcome::Matches(matches)) => {
            let code = run(&argv, &bin_name, matches);
            std::process::exit(code);
        }
        Err(err) => {
            // A missing required subcommand prints the help to stderr.
            if err.message.is_empty() {
                let cmd = last_command(&argv);
                let path = path_of(&argv, cmd);
                let help = help::render_help(cmd, &bin_name, &path_names(&path), term_width(), false);
                eprint!("{}", help);
                let _ = std::io::stderr().flush();
                std::process::exit(2);
            }
            eprint!("{}", err.render());
            let _ = std::io::stderr().flush();
            std::process::exit(2);
        }
    }
}

fn bin_name() -> String {
    std::env::args()
        .next()
        .map(|a| {
            std::path::Path::new(&a)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| a.clone())
        })
        .unwrap_or_else(|| "pueue".to_string())
}

fn path_names(path: &[&'static Cmd]) -> Vec<&str> {
    path.iter().map(|c| c.name).collect()
}

/// The command chain of the parsed arguments (used for error rendering).
fn last_command(argv: &[String]) -> &'static Cmd {
    let mut cmd: &'static Cmd = &cli::ROOT;
    for token in argv {
        if token.starts_with('-') {
            continue;
        }
        if let Some(sub) = cmd.find_sub(token) {
            cmd = sub;
        }
    }
    cmd
}

fn path_of(_argv: &[String], cmd: &'static Cmd) -> Vec<&'static Cmd> {
    // Walk the tree to find the path of the given command.
    fn find(cmd: &'static Cmd, target: &'static Cmd, path: &mut Vec<&'static Cmd>) -> bool {
        if std::ptr::eq(cmd, target) {
            return true;
        }
        for sub in cmd.subcommands {
            path.push(sub);
            if find(sub, target, path) {
                return true;
            }
            path.pop();
        }
        false
    }
    let mut path = Vec::new();
    let _ = find(&cli::ROOT, cmd, &mut path);
    path
}

fn term_width() -> usize {
    if let Some(width) = terminal_width() {
        return width;
    }
    help::DEFAULT_TERM_WIDTH
}

/// Width of the terminal that stdout is attached to.
fn terminal_width() -> Option<usize> {
    #[repr(C)]
    struct Winsize {
        ws_row: u16,
        ws_col: u16,
        ws_xpixel: u16,
        ws_ypixel: u16,
    }
    extern "C" {
        fn ioctl(fd: i32, request: u64, ...) -> i32;
    }
    const TIOCGWINSZ: u64 = 0x5413;
    let mut ws = Winsize {
        ws_row: 0,
        ws_col: 0,
        ws_xpixel: 0,
        ws_ypixel: 0,
    };
    let res = unsafe { ioctl(1, TIOCGWINSZ, &mut ws as *mut Winsize) };
    if res == 0 && ws.ws_col > 0 {
        Some(ws.ws_col as usize)
    } else {
        None
    }
}

fn run(_argv: &[String], bin_name: &str, matches: Box<parser::Matches>) -> i32 {
    let cmd = matches.cmd();
    if cmd.name == "completions" {
        let shell = matches
            .positionals
            .first()
            .cloned()
            .unwrap_or_default();
        let dir = matches.positionals.get(1).cloned();
        return complete::generate(&shell, dir.as_deref(), bin_name);
    }

    let verbose = matches.count("verbose");
    let config = matches.value("config").cloned();
    let profile = matches.value("profile").cloned();

    let settings = match settings::load(config.as_ref(), profile.as_ref(), verbose) {
        Ok(s) => s,
        Err(report) => return report_exit(&report),
    };
    let _ = settings;

    let secret = match client::read_secret() {
        Ok(s) => s,
        Err(report) => return report_exit(&report),
    };
    let _ = secret;

    let _client = match client::connect() {
        Ok(c) => c,
        Err(report) => return report_exit(&report),
    };

    // Reaching this point requires a running daemon.
    0
}

fn report_exit(report: &Report) -> i32 {
    eprint!("{}", report.render());
    let _ = std::io::stderr().flush();
    1
}
