//! Shell completion generation.

pub mod bash;
pub mod elvish;
pub mod fish;
pub mod nushell;
pub mod powershell;
pub mod zsh;

use crate::model::Cmd;
use crate::parser::Matches;

pub fn generate(shell: &str, dir: Option<&str>, bin_name: &str) -> i32 {
    let (variant, name, content) = match shell {
        "bash" => ("Bash", "pueue.bash", bash::generate()),
        "elvish" => ("Elvish", "pueue.elv", elvish::generate()),
        "fish" => ("Fish", "pueue.fish", fish::generate()),
        "power-shell" => ("PowerShell", "pueue.ps1", powershell::generate()),
        "zsh" => ("Zsh", "_pueue", zsh::generate()),
        "nushell" => ("Nushell", "pueue.nu", nushell::generate()),
        _ => return 0,
    };
    match dir {
        Some(dir) => {
            let path = std::path::Path::new(dir).join(name);
            match std::fs::write(&path, content) {
                Ok(_) => 0,
                Err(err) => {
                    let report = eyre::Report::new(
                        vec![
                            format!("Failed to generate completions for {}", variant),
                            format!("{}", err),
                        ],
                        eyre::LOC_COMPLETIONS,
                    );
                    eprint!("{}", report.render());
                    1
                }
            }
        }
        None => {
            print!("{}", content);
            let _ = std::io::stdout().flush();
            0
        }
    }
}

/// Walk the whole command tree, calling `f` for every command with its path.
pub fn walk(cmd: &'static Cmd, path: &mut Vec<&'static Cmd>, f: &mut dyn FnMut(&'static Cmd, &[&'static Cmd])) {
    f(cmd, path);
    for sub in cmd.subcommands {
        path.push(sub);
        walk(sub, path, f);
        path.pop();
    }
}
