//! UNIX signal parsing for the `kill` subcommand.

pub struct Signal {
    pub number: i32,
    pub name: &'static str,
}

const SIGNALS: &[(&'static str, i32)] = &[
    ("int", 2),
    ("kill", 9),
    ("term", 15),
    ("cont", 18),
    ("stop", 19),
];

pub fn parse(value: &str) -> Option<Signal> {
    if !value.is_empty() && value.bytes().all(|b| b.is_ascii_digit()) {
        let number: i32 = value.parse().ok()?;
        return SIGNALS
            .iter()
            .find(|(_, n)| *n == number)
            .map(|(name, n)| Signal {
                number: *n,
                name,
            });
    }
    let lower = value.to_lowercase();
    let name = lower.strip_prefix("sig").unwrap_or(&lower);
    SIGNALS
        .iter()
        .find(|(n, _)| *n == name)
        .map(|(name, number)| Signal {
            number: *number,
            name,
        })
}
