{"command": "cd /workspace; python3 - <<'EOF'
import sys, re
sys.path.insert(0,'/tmp')
from ptylib import run
def dump(cmd, long_form):
    argv = ["./executable"]+cmd.split()+[("--help" if long_form else "-h")]
    o = run(argv, cols=2000).replace('\r\n','\n')
    print("@@@@@ %s %s" % (cmd, "LONG" if long_form else "SHORT"))
    print("ABOUT:", repr(o.split("\nUsage:")[0].rstrip('\n')))
    cur=None
    for l in o.split('\n'):
        if l in ("Options:","Commands:","Arguments:"):
            cur=l[:-1]; continue
        if cur and l.startswith("  ") and not l.startswith("   "):
            body=l[2:]
            m=re.match(r'^(\S.*?)(  +)(.*)$', body)
            if m: print("  %s SPEC=%r HELP=%r" % (cur, m.group(1), m.group(3)))
for cmd in ["start","restart","log","parallel","enqueue","status"]:
    dump(cmd, True)
    dump(cmd, False)
EOF"}

