use crate::cli::{ROOT, HELP_SUBCMD};
use crate::help::{full_usage, smart_usage, spec_vals};
use crate::model::{Arg, Cmd, Kind, Positional};

/// Everything that was successfully parsed.
pub struct Matches {
    pub path: Vec<&'static Cmd>,
    pub values: Vec<(&'static Arg, Vec<String>)>,
    pub positionals: Vec<String>,
}

impl Matches {
    pub fn cmd(&self) -> &'static Cmd {
        self.path.last().copied().unwrap_or(&ROOT)
    }
    pub fn get(&self, id: &str) -> Option<&Vec<String>> {
        self.values
            .iter()
            .find(|(a, _)| a.id == id)
            .map(|(_, v)| v)
    }
    pub fn flag(&self, id: &str) -> bool {
        self.get(id).is_some()
    }
    pub fn value(&self, id: &str) -> Option<&String> {
        self.get(id).and_then(|v| v.first())
    }
    pub fn count(&self, id: &str) -> usize {
        self.get(id).map(|v| v.len()).unwrap_or(0)
    }
}

pub enum Outcome {
    Help {
        long: bool,
        cmd: &'static Cmd,
        path: Vec<&'static Cmd>,
    },
    Version,
    Matches(Box<Matches>),
}

/// An error that is rendered exactly like the original program does.
pub struct ClapError {
    pub message: String,
    pub detail: Option<String>,
    pub tip: Option<String>,
    pub usage: Option<String>,
}

impl ClapError {
    pub fn render(&self) -> String {
        let mut out = format!("error: {}\n", self.message);
        if let Some(d) = &self.detail {
            out.push_str(d);
            out.push('\n');
        }
        if let Some(t) = &self.tip {
            out.push('\n');
            out.push_str("  tip: ");
            out.push_str(t);
            out.push('\n');
        }
        if let Some(u) = &self.usage {
            out.push('\n');
            out.push_str("Usage: ");
            out.push_str(u);
            out.push('\n');
        }
        out.push('\n');
        out.push_str("For more information, try '--help'.\n");
        out
    }
}

/// Jaro similarity (the variant used by the original program).
fn jaro(a: &str, b: &str) -> f64 {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let (al, bl) = (a.len(), b.len());
    if al == 0 && bl == 0 {
        return 1.0;
    }
    if al == 0 || bl == 0 {
        return 0.0;
    }
    if al == 1 && bl == 1 {
        return if a[0] == b[0] { 1.0 } else { 0.0 };
    }
    let search_range = (al.max(bl) / 2) - 1;
    let mut consumed = vec![false; bl];
    let mut matches: Vec<(usize, usize)> = Vec::new();
    let mut transpositions = 0.0f64;
    let mut b_match_index = 0usize;
    for (i, a_elem) in a.iter().enumerate() {
        let min_bound = if i > search_range { i - search_range } else { 0 };
        let max_bound = (bl - 1).min(i + search_range);
        if min_bound > max_bound {
            continue;
        }
        for (j, b_elem) in b.iter().enumerate() {
            if min_bound <= j && j <= max_bound && a_elem == b_elem && !consumed[j] {
                consumed[j] = true;
                matches.push((i, j));
                if j < b_match_index {
                    transpositions += 1.0;
                }
                b_match_index = j;
                break;
            }
        }
    }
    let m = matches.len() as f64;
    if m == 0.0 {
        0.0
    } else {
        // The original counts half of the differing positions of both matched
        // sequences as transpositions.
        let a_seq: Vec<char> = matches.iter().map(|(i, _)| a[*i]).collect();
        let b_seq: Vec<char> = {
            let mut js: Vec<usize> = matches.iter().map(|(_, j)| *j).collect();
            js.sort_unstable();
            js.iter().map(|j| b[*j]).collect()
        };
        let diffs = a_seq
            .iter()
            .zip(b_seq.iter())
            .filter(|(x, y)| x != y)
            .count() as f64;
        let t = diffs / 2.0;
        (1.0 / 3.0) * ((m / al as f64) + (m / bl as f64) + ((m - t) / m))
    }
}

fn did_you_mean(input: &str, possible: &[&str]) -> Vec<String> {
    let mut candidates: Vec<(f64, String)> = possible
        .iter()
        .map(|p| (jaro(input, p), (*p).to_string()))
        .filter(|(c, _)| *c >= 0.7)
        .collect();
    candidates.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap_or(std::cmp::Ordering::Equal));
    candidates.into_iter().map(|(_, p)| p).collect()
}

/// All names (and hidden aliases) of the subcommands of `cmd`.
fn subcommand_names(cmd: &Cmd) -> Vec<&'static str> {
    let mut out = Vec::new();
    for sc in cmd.subcommands {
        out.push(sc.name);
        for alias in subcmd_alias::aliases_of(sc.name) {
            out.push(alias);
        }
    }
    out
}

fn tip_text(kind: &str, singular: &str, plural: &str, tips: &[String]) -> Option<String> {
    match tips.len() {
        0 => None,
        1 => Some(format!("{} exists: '{}'", singular, tips[0])),
        _ => Some(format!(
            "{}: {}",
            plural,
            tips.iter()
                .map(|t| format!("'{}'", t))
                .collect::<Vec<_>>()
                .join(", ")
        )),
    }
    .map(|s| format!("{} {}", kind, s))
}

fn invalid_subcommand(name: &str, candidates: &[&str], usage: String) -> ClapError {
    let tips = did_you_mean(name, candidates);
    let tip = tip_text(
        "some similar subcommands",
        "a similar subcommand",
        "some similar subcommands exist",
        &tips,
    );
    ClapError {
        message: format!("unrecognized subcommand '{}'", name),
        detail: None,
        tip,
        usage: Some(usage),
    }
}

fn invalid_value(value: &str, spec: &str, possible: &[&str], message: &str) -> ClapError {
    let detail = if possible.is_empty() {
        None
    } else {
        Some(format!("[possible values: {}]", possible.join(", ")))
    };
    let message = if detail.is_some() {
        format!("invalid value '{}' for '{}'", value, spec)
    } else {
        format!("invalid value '{}' for '{}': {}", value, spec, message)
    };
    let tip = if possible.is_empty() {
        None
    } else {
        let tips = did_you_mean(value, possible);
        tip_text(
            "some similar values",
            "a similar value",
            "some similar values exist",
            &tips,
        )
    };
    ClapError {
        message,
        detail,
        tip,
        usage: None,
    }
}

fn value_required(spec: &str, possible: &[&str]) -> ClapError {
    ClapError {
        message: format!(
            "a value is required for '{}' but none was supplied",
            spec
        ),
        detail: if possible.is_empty() {
            None
        } else {
            Some(format!("[possible values: {}]", possible.join(", ")))
        },
        tip: None,
        usage: None,
    }
}

fn unexpected_argument(
    cmd: &'static Cmd,
    token: &str,
    bin_name: &str,
    path: &[&'static Cmd],
    positional_hint: bool,
) -> ClapError {
    let tip = if positional_hint {
        Some(format!("to pass '{}' as a value, use '-- {}'", token, token))
    } else {
        None
    };
    ClapError {
        message: format!("unexpected argument '{}' found", token),
        detail: None,
        tip,
        usage: Some(full_usage(cmd, bin_name, path)),
    }
}

fn path_names(path: &[&'static Cmd]) -> Vec<&'static Cmd> {
    path.to_vec()
}

pub fn parse(argv: &[String], bin_name: &str) -> Result<Outcome, ClapError> {
    let mut cmd: &'static Cmd = &ROOT;
    let mut path: Vec<&'static Cmd> = Vec::new();
    let mut values: Vec<(&'static Arg, Vec<String>)> = Vec::new();
    let mut positionals: Vec<String> = Vec::new();
    let mut used: Vec<String> = Vec::new();
    let mut positional_idx = 0usize;
    let mut only_positional = false;
    let mut idx = 0usize;
    // State for the `help` subcommand.
    let mut help_mode = false;
    let mut help_base: &'static Cmd = &ROOT;
    let mut help_path: Vec<&'static Cmd> = Vec::new();

    while idx < argv.len() {
        let token = &argv[idx];
        idx += 1;

        if help_mode {
            match help_base.find_sub(token) {
                Some(sub) => {
                    help_base = sub;
                    help_path.push(sub);
                }
                None => {
                    return Err(ClapError {
                        message: format!("unrecognized subcommand '{}'", token),
                        detail: None,
                        tip: None,
                        usage: Some(full_usage(help_base, bin_name, &help_path)),
                    });
                }
            }
            continue;
        }

        if only_positional {
            let p = positional_at(cmd, positional_idx);
            validate_positional(p, token)?;
            push_positional(cmd, &mut positionals, &mut positional_idx, token)?;
            continue;
        }
        if token == "--" {
            only_positional = true;
            continue;
        }
        if token.starts_with("--") && token.len() > 2 {
            let body = &token[2..];
            let (name, inline) = match body.find('=') {
                Some(p) => (&body[..p], Some(body[p + 1..].to_string())),
                None => (body, None),
            };
            if name == "help" && cmd.find_long("help").is_some() {
                return Ok(Outcome::Help {
                    long: true,
                    cmd,
                    path: path.clone(),
                });
            }
            if name == "version" && cmd.find_long("version").is_some() {
                return Ok(Outcome::Version);
            }
            match cmd.find_long(name) {
                Some(arg) => {
                    if arg.takes_value() {
                        let value = match inline {
                            Some(v) => v,
                            None => {
                                if idx < argv.len() {
                                    let v = argv[idx].clone();
                                    idx += 1;
                                    v
                                } else {
                                    return Err(value_required(&arg.usage(), arg.possible));
                                }
                            }
                        };
                        validate_value(arg, &value)?;
                        if !arg.multi && values.iter().any(|(a, _)| a.id == arg.id) {
                            return Err(too_many(arg, bin_name, &path));
                        }
                        store(&mut values, arg, value, &mut used);
                    } else if inline.is_some() {
                        return Err(ClapError {
                            message: format!(
                                "unexpected value '{}' for '--{}' found; no more were expected",
                                inline.unwrap(),
                                name
                            ),
                            detail: None,
                            tip: None,
                            usage: Some(full_usage(cmd, bin_name, &path)),
                        });
                    } else {
                        if !arg.multi && values.iter().any(|(a, _)| a.id == arg.id) {
                            return Err(too_many(arg, bin_name, &path));
                        }
                        store(&mut values, arg, String::new(), &mut used);
                    }
                }
                None => {
                    return Err(unexpected_argument(
                        cmd,
                        &format!("--{}", name),
                        bin_name,
                        &path,
                        !cmd.positionals.is_empty(),
                    ))
                }
            }
            continue;
        }
        if token.starts_with('-') && token.len() > 1 {
            let chars: Vec<char> = token[1..].chars().collect();
            let mut ci = 0usize;
            while ci < chars.len() {
                let c = chars[ci];
                ci += 1;
                if c == 'h' && cmd.find_short('h').is_some() {
                    return Ok(Outcome::Help {
                        long: false,
                        cmd,
                        path: path.clone(),
                    });
                }
                if c == 'V' && cmd.find_short('V').is_some() {
                    return Ok(Outcome::Version);
                }
                match cmd.find_short(c) {
                    Some(arg) => {
                        if arg.takes_value() {
                            let rest: String = chars[ci..].iter().collect();
                            let value = if !rest.is_empty() {
                                ci = chars.len();
                                match rest.strip_prefix('=') {
                                    Some(v) => v.to_string(),
                                    None => rest,
                                }
                            } else if idx < argv.len() {
                                let v = argv[idx].clone();
                                idx += 1;
                                v
                            } else {
                                return Err(value_required(&arg.usage(), arg.possible));
                            };
                            validate_value(arg, &value)?;
                            if !arg.multi && values.iter().any(|(a, _)| a.id == arg.id) {
                                return Err(too_many(arg, bin_name, &path));
                            }
                            store(&mut values, arg, value, &mut used);
                        } else {
                            if !arg.multi && values.iter().any(|(a, _)| a.id == arg.id) {
                                return Err(too_many(arg, bin_name, &path));
                            }
                            store(&mut values, arg, String::new(), &mut used);
                        }
                    }
                    None => {
                        return Err(unexpected_argument(
                            cmd,
                            &format!("-{}", c),
                            bin_name,
                            &path,
                            !cmd.positionals.is_empty(),
                        ))
                    }
                }
            }
            continue;
        }
        // Positional or subcommand
        if !cmd.subcommands.is_empty() {
            if token == "help" {
                if let Some(sub) = cmd.find_sub("help") {
                    help_mode = true;
                    help_base = &ROOT;
                    help_path = Vec::new();
                    let _ = sub;
                    continue;
                }
            }
            if let Some(sub) = cmd.find_sub(token) {
                cmd = sub;
                path.push(sub);
                used.clear();
                positionals.clear();
                positional_idx = 0;
                continue;
            }
            if subcommand_names(cmd).iter().any(|a| *a == token.as_str()) {
                let target = cmd
                    .subcommands
                    .iter()
                    .find(|sc| subcmd_alias::aliases_of(sc.name).contains(&token.as_str()))
                    .unwrap();
                cmd = target;
                path.push(target);
                used.clear();
                positionals.clear();
                positional_idx = 0;
                continue;
            }
            return Err(invalid_subcommand(
                token,
                &subcommand_names(cmd),
                full_usage(cmd, bin_name, &path),
            ));
        }
        let p = positional_at(cmd, positional_idx);
        validate_positional(p, token)?;
        push_positional(cmd, &mut positionals, &mut positional_idx, token)?;
    }

    if help_mode {
        let target = if help_base.name == "help" && help_path.is_empty() {
            &HELP_SUBCMD
        } else {
            help_base
        };
        return Ok(Outcome::Help {
            long: true,
            cmd: target,
            path: help_path,
        });
    }

    // A required subcommand that is missing prints the help to stderr.
    if cmd.sub_required {
        return Err(ClapError {
            message: String::new(),
            detail: None,
            tip: None,
            usage: None,
        });
    }

    // Missing required positionals
    let mut missing: Vec<String> = Vec::new();
    let mut consumed = 0usize;
    for p in cmd.positionals {
        if p.required {
            if p.multi {
                if positionals.len() <= consumed {
                    missing.push(p.usage());
                }
            } else if consumed >= positionals.len() {
                missing.push(p.usage());
            }
        }
        consumed += if p.multi { usize::MAX } else { 1 };
    }
    if !missing.is_empty() {
        return Err(ClapError {
            message: "the following required arguments were not provided:".to_string(),
            detail: Some(
                missing
                    .iter()
                    .map(|m| format!("  {}", m))
                    .collect::<Vec<_>>()
                    .join("\n"),
            ),
            tip: None,
            usage: Some(smart_usage(cmd, bin_name, &path, &used)),
        });
    }

    Ok(Outcome::Matches(Box::new(Matches {
        path,
        values,
        positionals,
    })))
}

fn too_many(arg: &Arg, bin_name: &str, path: &[&'static Cmd]) -> ClapError {
    ClapError {
        message: format!(
            "the argument '{}' cannot be used multiple times",
            arg.usage_no_multi()
        ),
        detail: None,
        tip: None,
        usage: Some(full_usage(ROOT.find_sub_path(path).unwrap_or(&ROOT), bin_name, path)),
    }
}

fn positional_at(cmd: &'static Cmd, idx: usize) -> Option<&'static Positional> {
    if idx < cmd.positionals.len() {
        return Some(&cmd.positionals[idx]);
    }
    cmd.positionals.last().copied().filter(|p| p.multi)
}

fn validate_positional(p: Option<&'static Positional>, token: &str) -> Result<(), ClapError> {
    let p = match p {
        Some(p) => p,
        None => return Ok(()),
    };
    if !p.possible.is_empty() {
        if token.is_empty() {
            return Err(value_required(&p.usage(), p.possible));
        }
        if !p.possible.contains(&token) {
            return Err(invalid_value(token, &p.usage(), p.possible, ""));
        }
        return Ok(());
    }
    if matches!(
        p.id,
        "TASK_IDS" | "TASK_ID" | "TASK_ID_1" | "TASK_ID_2"
    ) {
        if let Err(e) = crate::nums::parse_number("usize", token) {
            return Err(invalid_value(token, &p.usage(), &[], &e));
        }
    }
    Ok(())
}

fn push_positional(
    cmd: &'static Cmd,
    positionals: &mut Vec<String>,
    idx: &mut usize,
    token: &str,
) -> Result<(), ClapError> {
    if *idx >= cmd.positionals.len() {
        if let Some(last) = cmd.positionals.last() {
            if last.multi {
                positionals.push(token.to_string());
                return Ok(());
            }
        }
        return Ok(());
    }
    let p = &cmd.positionals[*idx];
    positionals.push(token.to_string());
    if !p.multi {
        *idx += 1;
    }
    Ok(())
}

fn store(
    values: &mut Vec<(&'static Arg, Vec<String>)>,
    arg: &'static Arg,
    value: String,
    used: &mut Vec<String>,
) {
    if let Some((_, v)) = values.iter_mut().find(|(a, _)| a.id == arg.id) {
        v.push(value);
        return;
    }
    used.push(arg.usage());
    values.push((arg, vec![value]));
}

fn validate_value(arg: &'static Arg, value: &str) -> Result<(), ClapError> {
    match arg.id {
        "signal" => {
            if crate::signal::parse(value).is_none() {
                return Err(invalid_value(
                    value,
                    &arg.usage(),
                    &[],
                    "Matching variant not found",
                ));
            }
        }
        "status" => {
            if !matches!(value, "queued" | "running" | "success" | "done") {
                return Err(invalid_value(
                    value,
                    &arg.usage(),
                    &[],
                    "Matching variant not found",
                ));
            }
        }
        "delay" => {
            if crate::delay::parse(value).is_none() {
                return Err(invalid_value(
                    value,
                    &arg.usage(),
                    &[],
                    "could not parse as seconds or date expression",
                ));
            }
        }
        "lines" | "after" => {
            if let Err(e) = crate::nums::parse_number("usize", value) {
                return Err(invalid_value(value, &arg.usage(), &[], &e));
            }
        }
        "priority" => {
            if let Err(e) = crate::nums::parse_number("i32", value) {
                return Err(invalid_value(value, &arg.usage(), &[], &e));
            }
        }
        "config" | "working-directory" => {
            if value.is_empty() {
                return Err(value_required(&arg.usage(), &[]));
            }
        }
        "color" => {
            if !arg.possible.contains(&value) {
                return Err(invalid_value(value, &arg.usage(), arg.possible, ""));
            }
        }
        _ => {}
    }
    Ok(())
}

