{"command": "cd /workspace; cat > src/complete/fish.rs <<'RSEOF'
//! Fish completion script generation.

use crate::cli::ROOT;
use crate::help::spec_vals;
use crate::model::{Arg, Cmd};

fn fish_escape(s: &str) -> String {
    s.replace('\\', "\\\\").replace('\'', "\\'")
}

fn fish_quote(s: &str) -> String {
    format!("'{}'", fish_escape(s))
}

/// Fish completion hints for values.
fn value_hint(arg: &Arg) -> Option<String> {
    match arg.id {
        "config" => Some("-r -F".to_string()),
        "working-directory" => {
            Some("-r -f -a \"(__fish_complete_directories)\"".to_string())
        }
        _ => {
            let vals = spec_vals_possible(arg);
            if vals.is_empty() {
                None
            } else {
                let joined = vals
                    .iter()
                    .map(|v| format!("{}\\t''", v))
                    .collect::<Vec<_>>()
                    .join("\n");
                Some(format!("-r -f -a \"{}\"", joined))
            }
        }
    }
}

fn spec_vals_possible(arg: &Arg) -> Vec<&'static str> {
    arg.possible.to_vec()
}

fn fish_option(cond: &str, arg: &Arg, out: &mut String) {
    out.push_str("complete -c pueue -n ");
    out.push_str(&fish_quote(cond));
    out.push(' ');
    if let Some(s) = arg.short {
        out.push_str(&format!("-s {} ", s));
    }
    out.push_str(&format!("-l {} ", arg.long));
    out.push_str(&format!("-d {} ", fish_quote(arg.help)));
    if arg.takes_value() {
        out.push_str("-r ");
        match value_hint(arg) {
            Some(extra) => {
                out.push_str(&extra);
                out.push('\n');
            }
            None => {
                out.push('\n');
            }
        }
    } else {
        out.push('\n');
    }
}

fn fish_subcommand(cond: &str, name: &str, about: &str, out: &mut String) {
    out.push_str("complete -c pueue -n ");
    out.push_str(&fish_quote(cond));
    out.push_str(&format!(" -f -a \"{}\" ", name));
    out.push_str(&format!("-d {} ", fish_quote(about)));
    out.push('\n');
}

/// Options of a command in the order the fish generator emits them: options
/// that take a value first, then flags.
fn ordered_args(cmd: &Cmd) -> Vec<&'static Arg> {
    let mut values = Vec::new();
    let mut flags = Vec::new();
    for a in cmd.args {
        if a.takes_value() {
            values.push(a);
        } else {
            flags.push(a);
        }
    }
    values.extend(flags);
    values
}

fn needs_command_condition(path: &[&'static Cmd]) -> String {
    if path.is_empty() {
        "__fish_pueue_needs_command".to_string()
    } else {
        let names: Vec<&str> = path.iter().map(|c| c.name).collect();
        format!("__fish_pueue_using_subcommand {}", names.join(" "))
    }
}

fn child_condition(path: &[&'static Cmd], sub: &Cmd) -> String {
    let mut names: Vec<&str> = path.iter().map(|c| c.name).collect();
    names.push(sub.name);
    format!("__fish_pueue_using_subcommand {}", names.join(" "))
}

fn child_condition_seen(path: &[&'static Cmd], sub: &Cmd) -> String {
    let mut names: Vec<&str> = path.iter().map(|c| c.name).collect();
    let parent = names.pop().unwrap_or("");
    format!(
        "__fish_pueue_using_subcommand {}; and __fish_seen_subcommand_from {}",
        names.join(" "),
        sub.name
    )
}

fn emit(
    cmd: &'static Cmd,
    path: &[&'static Cmd],
    own_cond: &str,
    out: &mut String,
) {
    for arg in ordered_args(cmd) {
        fish_option(own_cond, arg, out);
    }
    for sub in cmd.subcommands {
        fish_subcommand(own_cond, sub.name, sub.about, out);
    }
    for sub in cmd.subcommands {
        let cond = child_condition_seen(path, sub);
        if sub.name == "help" {
            // The help subcommand completes the sibling subcommands.
            emit_help_subcommand(sub, path, &cond, out);
            continue;
        }
        emit_sub(sub, path, &cond, out);
    }
}

fn emit_sub(
    cmd: &'static Cmd,
    path: &[&'static Cmd],
    cond: &str,
    out: &mut String,
) {
    let mut new_path: Vec<&'static Cmd> = path.to_vec();
    new_path.push(cmd);
    let own_cond = if cmd.subcommands.is_empty() {
        cond.to_string()
    } else {
        let names: Vec<&str> = cmd.subcommands.iter().map(|c| c.name).collect();
        format!(
            "{}; and not __fish_seen_subcommand_from {}",
            cond,
            names.join(" ")
        )
    };
    emit(cmd, &new_path, &own_cond, out);
}

fn emit_help_subcommand(
    cmd: &'static Cmd,
    path: &[&'static Cmd],
    cond: &str,
    out: &mut String,
) {
    // The parent's subcommands are the ones the help command completes.
    let parent = path.last().copied().unwrap_or(&ROOT);
    let mut new_path: Vec<&'static Cmd> = path.to_vec();
    new_path.push(cmd);
    let names: Vec<&str> = parent.subcommands.iter().map(|c| c.name).collect();
    let own_cond = if names.is_empty() {
        cond.to_string()
    } else {
        format!(
            "{}; and not __fish_seen_subcommand_from {}",
            cond,
            names.join(" ")
        )
    };
    for sub in parent.subcommands {
        fish_subcommand(&own_cond, sub.name, sub.about, out);
    }
    for sub in parent.subcommands {
        if sub.name == "help" {
            continue;
        }
        let child_cond = format!("{}; and __fish_seen_subcommand_from {}", cond, sub.name);
        if sub.subcommands.is_empty() {
            continue;
        }
        let child_names: Vec<&str> = sub.subcommands.iter().map(|c| c.name).collect();
        let child_own = format!(
            "{}; and not __fish_seen_subcommand_from {}",
            child_cond,
            child_names.join(" ")
        );
        for arg in ordered_args(sub) {
            fish_option(&child_own, arg, out);
        }
        for c in sub.subcommands {
            fish_subcommand(&child_own, c.name, c.about, out);
        }
        for c in sub.subcommands {
            if c.name == "help" {
                continue;
            }
            let cc = format!("{}; and __fish_seen_subcommand_from {}", child_cond, c.name);
            for arg in ordered_args(c) {
                fish_option(&cc, arg, out);
            }
        }
    }
    let _ = new_path;
}

pub fn generate() -> String {
    let mut out = String::new();
    out.push_str("# Print an optspec for argparse to handle cmd's options that are independent of any subcommand.\n");
    out.push_str("function __fish_pueue_global_optspecs\n");
    out.push_str("\tstring join \\n");
    for arg in ROOT.args {
        let mut spec = String::new();
        match arg.short {
            Some(s) => {
                spec.push(s);
                spec.push('/');
            }
            None => {}
        }
        spec.push_str(arg.long);
        if arg.takes_value() {
            spec.push('=');
        }
        out.push(' ');
        out.push_str(&spec);
    }
    out.push_str("\nend\n\n");
    out.push_str(FISH_HELPERS);
    emit(&ROOT, &[], &needs_command_condition(&[]), &mut out);
