//! Shared traversal of the command tree used by the completion generators.
//!
//! The order matches the one the original generator uses: every command is
//! visited before its subcommands and the built in `help` command completes the
//! subcommands of its parent.

use crate::model::Cmd;

#[derive(Clone, Copy, PartialEq)]
pub enum Mode {
    /// A regular command: its options and its subcommands are completed.
    Normal,
    /// A subcommand of `help`: only its subcommands are completed.
    HelpChildren,
}

pub struct Item {
    pub cmd: &'static Cmd,
    pub path: Vec<&'static Cmd>,
    pub mode: Mode,
}

pub fn walk() -> Vec<Item> {
    let mut out = Vec::new();
    walk_cmd(&crate::cli::ROOT, Vec::new(), Mode::Normal, &mut out);
    out
}

fn walk_cmd(
    cmd: &'static Cmd,
    path: Vec<&'static Cmd>,
    mode: Mode,
    out: &mut Vec<Item>,
) {
    out.push(Item {
        cmd,
        path: path.clone(),
        mode,
    });
    match mode {
        Mode::Normal => {
            for sub in cmd.subcommands {
                let mut p = path.clone();
                p.push(sub);
                if sub.name == "help" {
                    out.push(Item {
                        cmd: sub,
                        path: p.clone(),
                        mode: Mode::Normal,
                    });
