                            continue;
                        }
                        let mut p2 = p.clone();
                        p2.push(s);
                        walk_cmd(s, p2, Mode::HelpChildren, out);
                    }
                    continue;
                }
                walk_cmd(sub, p, Mode::Normal, out);
            }
        }
        Mode::HelpChildren => {
            for sub in cmd.subcommands {
                if sub.name == "help" {
                    continue;
                }
                let mut p = path.clone();
                p.push(sub);
                walk_cmd(sub, p, Mode::HelpChildren, out);
            }
        }
    }
}

/// Path of a command joined with the given separator.
pub fn join_path(path: &[&'static Cmd], sep: &str, name: &str) -> String {
    let mut parts: Vec<&str> = path.iter().map(|c| c.name).collect();
    parts.push(name);
    parts.join(sep)
}
