        }
    } else {
        arg.help.replace('\n', " ")
    }
}

const HEAD: &str = "\nuse builtin;\nuse str;\n\nset edit:completion:arg-completer[pueue] = {|@words|\n    fn spaces {|n|\n        builtin:repeat $n ' ' | str:join ''\n    }\n    fn cand {|text desc|\n        edit:complex-candidate $text &display=$text' '(spaces (- 14 (wcswidth $text)))$desc\n    }\n    var command = 'pueue'\n    for word $words[1..-1] {\n        if (str:has-prefix $word '-') {\n            break\n        }\n        set command = $command';'$word\n    }\n    var completions = [\n";
const TAIL: &str = "    ]\n    $completions[$command]\n}\n";

pub fn generate() -> String {
    let mut out = String::new();
    out.push_str(HEAD);
    for item in walk() {
        let path = crate::complete::walk::join_path(&item.path, ";", item.cmd.name);
        out.push_str(&format!("        &'{}'= {{\n", path));
