                if let Some(s) = arg.short {
                    out.push_str(&format!("            cand -{} '{}'\n", s, help));
                }
                out.push_str(&format!(
                    "            cand --{} '{}'\n",
                    arg.long,
                    help
                ));
            }
        }
        let subcommands: Vec<_> = if item.mode == Mode::HelpChildren {
            item.cmd
                .subcommands
                .iter()
                .filter(|s| s.name != "help")
                .collect()
        } else if item.cmd.name == "help" {
            let parent = if item.path.len() >= 2 {
                item.path[item.path.len() - 2]
            } else {
                &crate::cli::ROOT
            };
            parent.subcommands.iter().collect()
        } else {
            item.cmd.subcommands.iter().collect()
        };
        for sub in subcommands {
            out.push_str(&format!(
                "            cand {} '{}'\n",
                sub.name,
                escape(sub.about)
            ));
        }
        out.push_str("        }\n");
    }
    out.push_str(TAIL);
    out
}
