//! PowerShell completion script generation.

use crate::complete::walk::{walk, Mode};
use crate::model::{Arg, Cmd};

fn escape(s: &str) -> String {
    s.replace('\'', "''")
}

fn arg_help(cmd: &'static Cmd, arg: &Arg) -> String {
    if arg.id == "help" {
        if cmd.has_long {
            "Print help (see more with '--help')".to_string()
        } else {
            "Print help".to_string()
        }
    } else {
        arg.help.replace('\n', " ")
    }
}

/// Options that take a value first, then flags.
fn ordered_args(cmd: &Cmd) -> Vec<&'static Arg> {
    let mut values = Vec::new();
    let mut flags = Vec::new();
    for a in cmd.args {
        if a.takes_value() {
            values.push(a);
        } else {
            flags.push(a);
        }
    }
    values.extend(flags);
    values
}

const HEAD: &str = "\nusing namespace System.Management.Automation\nusing namespace System.Management.Automation.Language\n\nRegister-ArgumentCompleter -Native -CommandName 'pueue' -ScriptBlock {\n    param($wordToComplete, $commandAst, $cursorPosition)\n\n    $commandElements = $commandAst.CommandElements\n    $command = @(\n        'pueue'\n        for ($i = 1; $i -lt $commandElements.Count; $i++) {\n            $element = $commandElements[$i]\n            if ($element -isnot [StringConstantExpressionAst] -or\n                $element.StringConstantType -ne [StringConstantType]::BareWord -or\n                $element.Value.StartsWith('-') -or\n                $element.Value -eq $wordToComplete) {\n                break\n        }\n        $element.Value\n    }) -join ';'\n\n    $completions = @(switch ($command) {\n";
const TAIL: &str = "    })\n\n    $completions.Where{ $_.CompletionText -like \"$wordToComplete*\" } |\n        Sort-Object -Property ListItemText\n}\n";

pub fn generate() -> String {
    let mut out = String::new();
    out.push_str(HEAD);
    for item in walk() {
        let mut names: Vec<&str> = vec![crate::cli::ROOT.name];
        names.extend(item.path.iter().map(|c| c.name));
        let path = names.join(";");
        out.push_str(&format!("        '{}' {{\n", path));
        if item.mode == Mode::Normal {
            for arg in ordered_args(item.cmd) {
                let help = escape(&arg_help(item.cmd, arg));
                if let Some(s) = arg.short {
                    let text = if s == 'V' {
                        format!("-{}", s)
                    } else {
                        format!("-{}", s)
                    };
                    let list = if arg.id == "version" && s == 'V' {
                        format!("-{} ", s)
                    } else {
                        text.clone()
                    };
                    out.push_str(&format!(
                        "            [CompletionResult]::new('{}', '{}', [CompletionResultType]::ParameterName, '{}')\n",
                        text, list, help
                    ));
                }
                out.push_str(&format!(
                    "            [CompletionResult]::new('--{}', '--{}', [CompletionResultType]::ParameterName, '{}')\n",
                    arg.long, arg.long, help
                ));
            }
        }
        let subcommands: Vec<_> = if item.mode == Mode::HelpChildren {
            item.cmd
                .subcommands
                .iter()
                .filter(|s| s.name != "help")
                .collect()
        } else if item.cmd.name == "help" {
            let parent = if item.path.len() >= 2 {
                item.path[item.path.len() - 2]
            } else {
                &crate::cli::ROOT
            };
            parent.subcommands.iter().collect()
        } else {
            item.cmd.subcommands.iter().collect()
        };
        for sub in subcommands {
            out.push_str(&format!(
                "            [CompletionResult]::new('{}', '{}', [CompletionResultType]::ParameterValue, '{}')\n",
                sub.name,
                sub.name,
                escape(sub.about)
            ));
        }
        out.push_str("            break\n        }\n");
    }
    out.push_str(TAIL);
    out
}
