//! Nushell completion script generation.

use crate::complete::walk::{walk, Mode};
use crate::model::{Arg, Cmd};

fn help_text(cmd: &'static Cmd, help: &str) -> String {
    help.replace('\n', " ")
}

fn arg_help(cmd: &'static Cmd, arg: &Arg) -> String {
    if arg.id == "help" {
        if cmd.has_long {
            "Print help (see more with '--help')".to_string()
        } else {
            "Print help".to_string()
        }
    } else {
        arg.help.replace('\n', " ")
    }
}

fn value_type(arg: &Arg) -> String {
    match arg.id {
        "config" | "working-directory" => "path".to_string(),
        _ => {
            if arg.possible.is_empty() {
                "string".to_string()
            } else {
                format!("string@\"nu-complete pueue {}\"", arg.id)
            }
        }
    }
}

/// Pad the specification so that the comment starts at a fixed column.
fn pad(spec: &str) -> String {
    let len = spec.chars().count();
    let target = std::cmp::max(30, len + 1);
    let mut out = spec.to_string();
    for _ in len..target {
        out.push(' ');
    }
    out
}

fn nu_option(cmd: &'static Cmd, arg: &Arg, out: &mut String) {
    let mut spec = String::new();
    spec.push_str("    --");
    spec.push_str(arg.long);
    if let Some(s) = arg.short {
        spec.push_str(&format!("(-{})", s));
    }
    if arg.takes_value() {
        spec.push_str(&format!(": {}", value_type(arg)));
    }
    let help = arg_help(cmd, arg);
    if help.is_empty() {
        out.push_str(&format!("{}\n", spec));
        return;
    }
    out.push_str(&format!("{} # {}\n", pad(&spec), help));
}

fn nu_positional(p: &crate::model::Positional, out: &mut String) {
    let mut spec = String::from("    ");
    if p.multi {
        spec.push_str("...");
    }
    spec.push_str(p.name);
    spec.push_str(": string");
    if p.help.is_empty() {
        out.push_str(&format!("{}\n", spec));
        return;
    }
    out.push_str(&format!("{} # {}\n", pad(&spec), help_text_cmd(p.help)));
}

fn help_text_cmd(help: &str) -> String {
    help.replace('\n', " ")
}

const HEAD_START: &str = "module completions {\n";
const TAIL: &str = "}\n\nexport use completions *\n";

pub fn generate() -> String {
    let mut out = String::new();
    out.push_str(HEAD_START);
    out.push('\n');
    // Value completions for arguments with a fixed set of possible values.
    for item in walk() {
        if item.mode != Mode::Normal {
            continue;
        }
        for arg in item.cmd.args {
            if arg.possible.is_empty() {
                continue;
            }
            let name = if item.path.is_empty() {
                format!("nu-complete pueue {}", arg.id)
            } else {
                let mut names: Vec<&str> = vec![crate::cli::ROOT.name];
                names.extend(item.path.iter().map(|c| c.name));
                format!(
                    "nu-complete pueue {} {}",
                    names.join(" "),
                    arg.id
                )
            };
            out.push_str(&format!("  def \"{}\" [] {{\n", name));
            out.push_str("    [ ");
            for v in arg.possible {
                out.push_str(&format!("\"{}\" ", v));
            }
            out.push_str("]\n");
            out.push_str("  }\n\n");
        }
    }
    for item in walk() {
        out.push('\n');
        let about = if item.cmd.name == "help" && item.cmd.about.is_empty() {
            String::new()
        } else {
            help_text(item.cmd, item.cmd.about)
