use crate::complete::walk::{walk, Mode};
use crate::model::{Arg, Cmd};

fn help_text(cmd: &'static Cmd, help: &str) -> String {
    help.replace('\n', " ")
}

fn arg_help(cmd: &'static Cmd, arg: &Arg) -> String {
    if arg.id == "help" {
        if cmd.has_long {
            "Print help (see more with '--help')".to_string()
        } else {
            "Print help".to_string()
        }
    } else {
        arg.help.replace('\n', " ")
    }
}

fn value_type(arg: &Arg) -> String {
    match arg.id {
        "config" | "working-directory" => "path".to_string(),
        _ => {
            if arg.possible.is_empty() {
                "string".to_string()
            } else {
                format!("string@\"nu-complete pueue {}\"", arg.id)
            }
        }
    }
}

/// Pad the specification so that the comment starts at a fixed column.
fn pad(spec: &str) -> String {
    let len = spec.chars().count();
    let target = std::cmp::max(30, len + 1);
    let mut out = spec.to_string();
    for _ in len..target {
        out.push(' ');
    }
    out
}

fn nu_option(cmd: &'static Cmd, arg: &Arg, out: &mut String) {
    let mut spec = String::new();
    spec.push_str("    --");
    spec.push_str(arg.long);
    if let Some(s) = arg.short {
        spec.push_str(&format!("(-{})", s));
    }
    if arg.takes_value() {
        spec.push_str(&format!(": {}", value_type(arg)));
    }
    let help = arg_help(cmd, arg);
    if help.is_empty() {
        out.push_str(&format!("{}\n", spec));
        return;
    }
    out.push_str(&format!("{} # {}\n", pad(&spec), help));
}

