//! Bash completion script generation.

use crate::complete::walk::{walk, Mode};
use crate::model::{Arg, Cmd};

fn cmd_name(path: &[&'static Cmd]) -> String {
    let mut names: Vec<&str> = vec![crate::cli::ROOT.name];
    names.extend(path.iter().map(|c| c.name));
    names.join("__")
}

fn depth(path: &[&'static Cmd]) -> usize {
    path.len() + 1
}

/// Options that take a value first, then flags.
fn ordered_args(cmd: &Cmd) -> Vec<&'static Arg> {
    let mut values = Vec::new();
    let mut flags = Vec::new();
    for a in cmd.args {
        if a.takes_value() {
            values.push(a);
        } else {
            flags.push(a);
        }
    }
    values.extend(flags);
    values
}

fn arg_help(cmd: &'static Cmd, arg: &Arg) -> String {
    if arg.id == "help" {
        if cmd.has_long {
            "Print help (see more with '--help')".to_string()
        } else {
            "Print help".to_string()
        }
    } else {
        arg.help.replace('\n', " ")
    }
}

fn subcommands_of(item_cmd: &'static Cmd, path: &[&'static Cmd], mode: Mode) -> Vec<&'static Cmd> {
    if mode == Mode::HelpChildren {
        return item_cmd
            .subcommands
            .iter()
            .filter(|s| s.name != "help")
            .copied()
            .collect();
    }
    if item_cmd.name == "help" {
        let parent = if path.len() >= 2 {
            path[path.len() - 2]
        } else {
            &crate::cli::ROOT
        };
        return parent.subcommands.to_vec();
    }
    item_cmd.subcommands.to_vec()
}

