const DIR_CASE: &str = "                    COMPREPLY=()\n                    if [[ \"${BASH_VERSINFO[0]}\" -ge 4 ]]; then\n                        compopt -o plusdirs\n                    fi\n                    return 0\n";
const PLAIN_CASE: &str = "                    COMPREPLY=($(compgen -f \"${cur}\"))\n                    return 0\n";

fn value_case(arg: &Arg) -> String {
    match arg.id {
        "config" => FILE_CASE.to_string(),
        "working-directory" => DIR_CASE.to_string(),
        _ => PLAIN_CASE.to_string(),
    }
