            key,
            format!("{}_{}", {
                let mut names: Vec<&str> = vec![crate::cli::ROOT.name];
                names.extend(
                    items
                        .iter()
                        .find(|i| i
                            .cmd
                            .subcommands
                            .iter()
                            .any(|s| s.name == name.as_str()))
                        .map(|_| ())
                        .is_none()
                        .then_some(Vec::<&'static str>::new())
                        .unwrap_or_default(),
                );
                key.split(',').next().unwrap_or("")
            }, name),
        ));
    }
    out.push_str("            *)\n                ;;\n        esac\n    done\n\n");
    out
}
