{"command": "cd /workspace; cat > src/complete/zsh.rs <<'RSEOF'
//! Zsh completion script generation.

use crate::complete::walk::{walk, Mode};
use crate::model::{Arg, Cmd};

fn esc(s: &str) -> String {
    s.replace('\\', "\\\\")
        .replace('\'', "'\\''")
        .replace(':', "\\:")
        .replace('`', "\\`")
}

fn arg_help(cmd: &'static Cmd, arg: &Arg) -> String {
    if arg.id == "help" {
        if cmd.has_long {
            "Print help (see more with '--help')".to_string()
        } else {
            "Print help".to_string()
        }
    } else {
        arg.help.replace('\n', " ")
    }
}

/// Options that conflict with the given argument of a command.
fn conflicts_of(cmd_name: &str, arg_id: &str) -> Vec<&'static str> {
    match (cmd_name, arg_id) {
        ("add", "delay") => vec!["immediate"],
        ("add", "immediate") => vec!["stashed"],
        ("add", "follow") => vec!["print-task-id"],
        ("add", "stashed") => vec!["immediate"],
        ("add", "group") => vec!["all"],
        ("stash", "group")
        | ("enqueue", "group")
        | ("start", "group")
        | ("pause", "group")
        | ("kill", "group")
        | ("wait", "group") => vec!["all"],
        ("restart", "failed-in-group") => vec!["all-failed"],
        ("restart", "immediate") => vec!["stashed"],
        ("log", "lines") => vec!["full"],
        _ => vec![],
    }
}

fn conflict_prefix(cmd: &'static Cmd, arg: &Arg) -> String {
    let ids = conflicts_of(cmd.name, arg.id);
    if ids.is_empty() {
        return String::new();
    }
    let mut specs: Vec<String> = Vec::new();
    for id in ids {
        if let Some(other) = cmd.find_long(id) {
            if let Some(s) = other.short {
                specs.push(format!("-{}", s));
            }
            specs.push(format!("--{}", other.long));
        }
    }
    format!("({}) ", specs.join(" "))
}

fn value_completer(arg: &Arg) -> &'static str {
    match arg.id {
        "config" => ":CONFIG:_files",
        "working-directory" => ":working-directory:_files -/",
        _ => "",
    }
}

fn opt_spec(cmd: &'static Cmd, arg: &Arg) -> String {
    let multi = if arg.multi { "*" } else { "" };
    let take = if arg.takes_value() { "+" } else { "" };
    let prefix = conflict_prefix(cmd, arg);
    let help = esc(&arg_help(cmd, arg));
    if !arg.takes_value() {
        let mut out = String::new();
        if let Some(s) = arg.short {
            out.push_str(&format!("'{}{}{}{}[{}]' \\\n", multi, prefix, s, take, help));
        }
        out.push_str(&format!(
            "'{}{}--{}{}[{}]' \\\n",
            multi, prefix, arg.long, take, help
        ));
        return out;
    }
    let mut out = String::new();
    // The value name and completer
    let (value, completer) = if !arg.possible.is_empty() {
        (
            format!(
                ":{}:({})",
                arg.value_name.unwrap_or(""),
                arg.possible.join(" ")
            ),
            "",
        )
    } else {
        (format!(":{}", arg.value_name.unwrap_or("")), "")
    };
    let suffix = if arg.id == "config" {
        ":CONFIG:_files"
    } else if arg.id == "working-directory" {
        ":working-directory:_files -/"
    } else {
        &value
    };
    if let Some(s) = arg.short {
        out.push_str(&format!(
            "'{}{}{}{}[{}]{}' \\\n",
            multi, prefix, s, take, help, suffix
        ));
    }
    out.push_str(&format!(
        "'{}{}--{}={}{}[{}]{}' \\\n",
        multi, prefix, arg.long, take, help, suffix
    ));
    out
}

fn positional_spec(p: &crate::model::Positional) -> String {
    let multi = if p.multi { "*" } else { "" };
    let colon = if p.multi { "::" } else { ":" };
    let help = if p.help.is_empty() {
        String::new()
    } else {
        format!(" -- {}", esc(p.help))
    };
    let completer = if !p.possible.is_empty() {
        format!("({})", p.possible.join(" "))
    } else if p.id == "command" {
        "_cmdambivalent".to_string()
    } else {
        "_default".to_string()
    };
    format!(
        "'{}{}{}{}:{}' \\\n",
        multi, colon, p.id, help, completer
    )
}

fn cmd_name(path: &[&'static Cmd]) -> String {
    let mut names: Vec<&str> = vec![crate::cli::ROOT.name];
    names.extend(path.iter().map(|c| c.name));
    names.join("__")
}

fn path_str(path: &[&'static Cmd]) -> String {
    let mut names: Vec<&str> = vec![crate::cli::ROOT.name];
    names.extend(path.iter().map(|c| c.name));
    names.join(" ")
}

fn subcommands_of(item_cmd: &'static Cmd, path: &[&'static Cmd], mode: Mode) -> Vec<&'static Cmd> {
    if mode == Mode::HelpChildren {
        return item_cmd
            .subcommands
            .iter()
            .filter(|s| s.name != "help")
            .collect();
    }
    if item_cmd.name == "help" {
        let parent = if path.len() >= 2 {
            path[path.len() - 2]
        } else {
            &crate::cli::ROOT
        };
        return parent.subcommands.iter().collect();
    }
    item_cmd.subcommands.iter().collect()
}

fn arguments_block(item_cmd: &'static Cmd, item_path: &[&'static Cmd], mode: Mode) -> String {
    let mut out = String::from("_arguments \"${_arguments_options[@]}\" : \\\n");
    if mode == Mode::Normal {
        for arg in item_cmd.args {
            out.push_str(&opt_spec(item_cmd, arg));
        }
    }
    if mode == Mode::Normal && item_cmd.name != "help" {
        for p in item_cmd.positionals {
            out.push_str(&positional_spec(p));
        }
    }
    let subs = subcommands_of(item_cmd, item_path, mode);
    if !subs.is_empty() {
        let fname = cmd_name(item_path);
        let state = item_cmd
            .subcommands
            .iter()
            .map(|c| c.name)
            .collect::<Vec<_>>()
            .join(" ");
        let _ = state;
        out.push_str(&format!("\":: :_{}_commands\" \\\n", fname));
        out.push_str(&format!("\"*::: :->{}\" \\\n", item_cmd.name));
    }
    out.push_str("&& ret=0\n");
    out
}

pub fn generate() -> String {
    let items = walk();
    let mut out = String::new();
    out.push_str("#compdef pueue\n\nautoload -U is-at-least\n\n_pueue() {\n    typeset -A opt_args\n    typeset -a _arguments_options\n    local ret=1\n\n    if is-at-least 5.2; then\n        _arguments_options=(-s -S -C)\n    else\n        _arguments_options=(-s -C)\n    fi\n\n    local context curcontext=\"$curcontext\" state line\n");
    let _ = &items;
    out
}
